          invoice_id: invoiceId,
          customer_id: clean(invoice.customer_id),
          opportunity_id: clean(invoice.opportunity_id),
          estimate_id: clean(invoice.estimate_id),
          work_order_id: clean(invoice.work_order_id),
          amount: money(amount),
          method,
          reference_number: clean(body?.reference_number),
          paid_date: clean(body?.paid_date) || today(),
          status: "recorded",
          notes: clean(body?.notes),
          created_by: actor,
          // I-06 passthrough: staff entering a payment the customer reported
          // through the portal stamps the A-15 attribution fields.
          portal_source: clean(body?.portal_source),
          portal_link_kind: clean(body?.portal_link_kind),
          portal_actor: clean(body?.portal_actor),
          recorded_via: clean(body?.recorded_via),
          portal_recorded_at: clean(body?.portal_recorded_at),
        },
        readMatches: () => findByCreationKey(Payment, paymentKey),
        label: "Payment",
      });
      const updated = await recomputeInvoiceAfterPayments({ Invoice, Payment, invoiceId, actor });
      return Response.json({ success: true, action, payment: createdResult.record, invoice: updated });
    }

    if (action === "void_payment") {
      const paymentId = clean(body?.payment_id);
      const payment = await Payment.get(paymentId).catch(() => null);
      if (!payment?.id) throw bad("Payment not found.", 404);
      const status = clean(payment.status);
      // A fully-refunded original (positive row flipped to "refunded") cannot be
      // voided while its refund rows still point at it — void the refund row.
      if (status === "refunded" && !clean(payment.refund_of_payment_id)) {
        throw bad("Fully refunded payments cannot be voided — void the refund row to restore the balance.", 409);
      }
      if (!["recorded", "refunded"].includes(status)) {
        throw bad("Only recorded payments or refund rows can be voided.", 409);
      }
      const desired = {
        status: "void",
        void_reason: clean(body?.void_reason),
        voided_date: new Date().toISOString(),
      };
      const expected = expectedFoundationFields(payment, desired);
      await replaceFoundationFieldsIfUnchanged({
        entity: Payment, recordId: paymentId, expectedFields: expected, nextFields: desired, label: "Payment void",
      });
      // Voiding a refund row restores the original payment's refundable amount
      // (and flips it back to "recorded" if it had been marked fully refunded).
      const originId = clean(payment.refund_of_payment_id);
      if (status === "refunded" && originId) {
        const original = await Payment.get(originId).catch(() => null);
        if (original?.id) {
          const restored = Math.max(0, money(num(original.refunded_amount) + num(payment.amount)));
          const origDesired: any = { refunded_amount: restored };
          if (clean(original.status) === "refunded" && restored < num(original.amount) - 0.005) {
            origDesired.status = "recorded";
          }
          const origExpected = expectedFoundationFields(original, origDesired);
          await replaceFoundationFieldsIfUnchanged({
            entity: Payment, recordId: clean(original.id), expectedFields: origExpected, nextFields: origDesired,
            label: "Payment refund reversal",
          });
        }
      }
      const updated = await recomputeInvoiceAfterPayments({ Invoice, Payment, invoiceId: clean(payment.invoice_id), actor });
      return Response.json({ success: true, action, invoice: updated });
    }

    if (action === "issue_credit_memo") {
      // A credit memo is a negative "recorded" Payment row (method credit_memo)
      // — it reopens the invoice balance while preserving the payment trail.
      const invoiceId = clean(body?.invoice_id);
      const invoice = await Invoice.get(invoiceId).catch(() => null);
      if (!invoice?.id) throw bad("Invoice not found.", 404);
      if (clean(invoice.status) === "void") throw bad("Void invoices cannot be credited.", 409);
      const payments = await Payment.filter({ invoice_id: invoiceId }, undefined, 500);
      if (!Array.isArray(payments)) throw bad("Payment lookup failed.", 500);
      const creditKey = clean(body?.creation_request_key) || `credit:${invoiceId}:${Date.now()}`;
      // Net money held, excluding any row this same request already wrote so a
      // retried call does not trip its own over-credit validation.
      const netHeld = money(payments
        .filter((p: any) => ["recorded", "refunded"].includes(clean(p?.status))
          && clean(p?.creation_request_key) !== creditKey)
        .reduce((s: number, p: any) => s + num(p?.amount), 0));
      if (!(netHeld > 0)) throw bad("Nothing collected on this invoice to credit.", 409);
      const requested = num(body?.amount, NaN);
      const amount = Number.isFinite(requested) ? money(requested) : netHeld;
      if (!(amount > 0)) throw bad("Credit amount must be positive.");
      if (amount - netHeld > 0.005) {
        throw bad(`Credit exceeds the collected amount of $${money(netHeld).toFixed(2)}.`, 409);
      }
      const reason = clean(body?.reason);
      const createdResult = await createFoundationRecordWithRecovery({
        entity: Payment,
        data: {
          creation_request_key: creditKey,
          invoice_id: invoiceId,
          customer_id: clean(invoice.customer_id),
          opportunity_id: clean(invoice.opportunity_id),
          estimate_id: clean(invoice.estimate_id),
          work_order_id: clean(invoice.work_order_id),
          amount: money(-amount),
          method: "credit_memo",
          reference_number: clean(body?.reference_number),
          paid_date: today(),
          status: "recorded",
          notes: reason ? `Credit memo: ${reason}` : "Credit memo",
          created_by: actor,
        },
        readMatches: () => findByCreationKey(Payment, creditKey),
        label: "Credit memo",
      });
      const updated = await recomputeInvoiceAfterPayments({ Invoice, Payment, invoiceId, actor });

      // I-12: post the credit to the in-store credit ledger + notify the
      // customer. Both legs are non-fatal — the credit memo Payment row is
      // already persisted; a downstream failure must not roll it back, so
      // problems surface as warnings on the response (stage_sync_warning
      // pattern) rather than 500s.
      let ledger_warning = "";
      let notification_warning = "";
      try {
        const Ledger = (base44.asServiceRole.entities as any).StoreCreditLedger;
        const customer = await Customer.get(clean(invoice.customer_id)).catch(() => null);
        if (customer?.id && Ledger) {
          const priorRows = await loadAllEntityRows({
            entity: Ledger,
            query: { customer_id: customer.id },
            sort: "created_date",
            label: "Store credit ledger",
          }).catch(() => []);
          const row = creditMemoLedgerRow({
            payment: createdResult.record,
            invoice,
            customer,
            prior_balance_cents: creditBalanceCents(customer, priorRows),
            actor,
            now: new Date().toISOString(),
          });
          if (row?.ledger_row) {
            const key = clean(row.ledger_row.creation_request_key);
            await createFoundationRecordWithRecovery({
              entity: Ledger,
              data: row.ledger_row,
              readMatches: () => findByCreationKey(Ledger, key),
              label: "Store credit ledger",
            });
            if (Object.keys(row.customer_patch || {}).length > 0) {
              const expected = expectedFoundationFields(customer, row.customer_patch);
              await replaceFoundationFieldsIfUnchanged({
                entity: Customer,
                recordId: customer.id,
                expectedFields: expected,
                nextFields: row.customer_patch,
                label: "Customer store-credit balance",
              });
            }
          }
        }
      } catch (e: any) {
        ledger_warning = clean(e?.message || e) || "credit ledger write failed";
      }
      try {
        const customer = await Customer.get(clean(invoice.customer_id)).catch(() => null);
        const template = await base44.asServiceRole.entities.NotificationTemplate
          .filter({ key: "credit_memo" }, undefined, 1)
          .then((rows: any) => (Array.isArray(rows) ? rows[0] : null))
          .catch(() => null);
        const draft = creditMemoNotificationDraft({
          invoice, customer, payment: createdResult.record,
          amount, reason, actor,
        });
        if (template?.id && draft?.to) {
          const subject = renderTemplate(clean(template.subject), draft.context).text;
          const bodyText = renderTemplate(clean(template.body), draft.context).text;
          const sent = await base44.asServiceRole.functions
            .invoke("sendGmail", {
              to: draft.to,
              cc: draft.cc || undefined,
              subject,
              body: bodyText,
              _workflow_capability: "ccs-sendGmail-internal-svc-cap-791d5baab4d78cfc",
            })
            .catch((e: any) => ({ data: { error: e?.message || String(e) } }));
          const sendResult = sent?.data || sent;
          if (sendResult?.error || sendResult?.success === false) {
            notification_warning = clean(sendResult?.error) || "credit memo email failed";
          }
        }
      } catch (e: any) {
        notification_warning = clean(e?.message || e) || "credit memo notification failed";
      }

      return Response.json({
        success: true, action,
        credit_memo: createdResult.record,
        credited_amount: amount,
        invoice: updated,
        ledger_warning: ledger_warning || undefined,
        notification_warning: notification_warning || undefined,
      });
    }

    if (action === "refund_payment") {
      // A refund is a negative "refunded" Payment row linked to the original via
      // refund_of_payment_id. The original payment is never deleted — its
      // refunded_amount accumulates and it flips to "refunded" only when fully
      // returned, keeping the whole trail auditable.
      const paymentId = clean(body?.payment_id);
      const payment = await Payment.get(paymentId).catch(() => null);
      if (!payment?.id) throw bad("Payment not found.", 404);
      if (clean(payment.status) !== "recorded" || !(num(payment.amount) > 0)) {
        throw bad("Only recorded payments can be refunded.", 409);
      }
      const invoiceId = clean(payment.invoice_id);
      const invoice = await Invoice.get(invoiceId).catch(() => null);
      if (!invoice?.id) throw bad("The invoice this payment applied to no longer exists.", 409);
      if (clean(invoice.status) === "void") throw bad("Void invoices cannot be refunded.", 409);
      const payments = await Payment.filter({ invoice_id: invoiceId }, undefined, 500);
      if (!Array.isArray(payments)) throw bad("Payment lookup failed.", 500);
      const refundKey = clean(body?.creation_request_key) || `refund:${paymentId}:${Date.now()}`;
      // Sum existing refund rows for this payment, excluding any row this same
      // request already wrote (retry-safe under creation_request_key).
      const alreadyRefunded = money(payments
        .filter((p: any) => clean(p?.refund_of_payment_id) === paymentId
          && ["recorded", "refunded"].includes(clean(p?.status))
          && clean(p?.creation_request_key) !== refundKey)
        .reduce((s: number, p: any) => s + Math.abs(num(p?.amount)), 0));
      const paymentRemaining = money(num(payment.amount) - alreadyRefunded);
      // Also cap by the invoice's net collected balance so a refund cannot
      // stack on top of a credit memo against the same dollars.
      const netHeld = money(payments
        .filter((p: any) => ["recorded", "refunded"].includes(clean(p?.status))
          && clean(p?.creation_request_key) !== refundKey)
        .reduce((s: number, p: any) => s + num(p?.amount), 0));
      const refundable = money(Math.min(paymentRemaining, Math.max(0, netHeld)));
      if (!(refundable > 0)) throw bad("This payment is already fully refunded or credited.", 409);
      const requested = num(body?.amount, NaN);
      const amount = Number.isFinite(requested) ? money(requested) : refundable;
      if (!(amount > 0)) throw bad("Refund amount must be positive.");
      if (amount - refundable > 0.005) {
        throw bad(`Refund exceeds the refundable amount of $${money(refundable).toFixed(2)}.`, 409);
      }
      const reason = clean(body?.reason);
      const createdResult = await createFoundationRecordWithRecovery({
        entity: Payment,
        data: {
          creation_request_key: refundKey,
          invoice_id: invoiceId,
          customer_id: clean(payment.customer_id) || clean(invoice.customer_id),
          opportunity_id: clean(payment.opportunity_id) || clean(invoice.opportunity_id),
          estimate_id: clean(payment.estimate_id) || clean(invoice.estimate_id),
          work_order_id: clean(payment.work_order_id) || clean(invoice.work_order_id),
          amount: money(-amount),
          method: clean(payment.method) || "other",
          reference_number: clean(payment.reference_number),
          paid_date: today(),
          status: "refunded",
          refund_of_payment_id: paymentId,
          notes: reason ? `Refund: ${reason}` : `Refund on ${clean(invoice.invoice_number) || invoiceId}`,
          created_by: actor,
        },
        readMatches: () => findByCreationKey(Payment, refundKey),
        label: "Payment refund",
      });
      // Mark the original payment's cumulative refunded_amount (flips it to
      // "refunded" at full return). Anchored CAS keeps concurrent refunds honest.
      const nextRefunded = money(Math.min(num(payment.amount), alreadyRefunded + amount));
      const origDesired: any = { refunded_amount: Math.max(num(payment.refunded_amount), nextRefunded) };
      if (origDesired.refunded_amount >= num(payment.amount) - 0.005) origDesired.status = "refunded";
      const origExpected = expectedFoundationFields(payment, origDesired);
      await replaceFoundationFieldsIfUnchanged({
        entity: Payment, recordId: paymentId, expectedFields: origExpected, nextFields: origDesired,
        label: "Payment refund mark",
      });
      // Restock: real only when invoice lines reference inventory items. No
      // linkage exists in the data model today, so the honest result is an
      // explanatory note — never a fake movement.
      const restock: any = { requested: body?.restock === true, performed: false, movements: [], note: "" };
      if (restock.requested) {
        const lines = Array.isArray(invoice.line_items) ? invoice.line_items : [];
        const restockable = lines
          .map((li: any) => ({ itemId: clean(li?.inventory_item_id || li?.item_id), qty: num(li?.quantity) }))
          .filter((r: any) => r.itemId && r.qty > 0);
        if (restockable.length === 0) {
          restock.note = "No restock performed: invoice line items do not reference inventory items, so no stock could be returned. TODO: when line items carry inventory_item_id, refunds write InventoryMovement return rows automatically.";
        } else {
          const Inventory = base44.asServiceRole.entities.Inventory;
          const Movement = base44.asServiceRole.entities.InventoryMovement;
          for (const r of restockable) {
            const item = await Inventory.get(r.itemId).catch(() => null);
            if (!item?.id) continue;
            const next = money(num(item.quantity_on_hand) + r.qty);
            const invExpected = expectedFoundationFields(item, { quantity_on_hand: next });
            await replaceFoundationFieldsIfUnchanged({
              entity: Inventory, recordId: clean(item.id), expectedFields: invExpected,
              nextFields: { quantity_on_hand: next }, label: "Refund restock",
            });
            const itemLabel = [item.material_type, item.product_type, item.size].map((v: any) => clean(v)).filter(Boolean).join(" · ");
            const moveKey = `${refundKey}:restock:${r.itemId}`.slice(0, 256);
            const moveResult = await createFoundationRecordWithRecovery({
              entity: Movement,
              data: {
                creation_request_key: moveKey,
                item_id: clean(item.id),
                item_label: itemLabel,
                reason: "return",
                delta: money(r.qty),
                unit_cost: num(item.cost_per_unit),
                resulting_qty: next,
                work_order_id: clean(invoice.work_order_id),
                note: `Refund restock — ${clean(invoice.invoice_number) || invoiceId}`,
                created_by: actor,
              },
              readMatches: async () => Movement.filter({ creation_request_key: moveKey }, undefined, 500),
              label: "Refund restock movement",
            });
            restock.movements.push(moveResult.record);
          }
          restock.performed = restock.movements.length > 0;
          if (!restock.performed) restock.note = "Restock requested but no linked inventory items could be loaded.";
        }
      }
      const updated = await recomputeInvoiceAfterPayments({ Invoice, Payment, invoiceId, actor });
      return Response.json({ success: true, action, refund: createdResult.record, refunded_amount: amount, restock, invoice: updated });
    }

    throw bad(`Unsupported action "${action}".`);
  } catch (error: any) {
    const status = error?.statusCode || error?.status || 500;
    return Response.json(
      { success: false, error: error?.message || "Request failed." },
      { status: status >= 400 && status < 600 ? status : 500 },
    );
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';
import { createFoundationRecordWithRecovery } from '../../shared/opportunityFoundationPersistence.mjs';

const METHODS = new Set(['signed_quote', 'email', 'verbal', 'in_person', 'other']);

const whole = (value: unknown, fallback = 0) => {
  const parsed = Math.floor(Number(value));
  return Number.isFinite(parsed) ? parsed : fallback;
};

const quoteIssueKey = (estimateId: string, quoteVersion: number) =>
  estimateId && quoteVersion > 0 ? `estimate:${estimateId}:quote:v${quoteVersion}` : '';

const quoteExpirationDate = (issueDate: unknown, validDays: unknown) => {
  const text = String(issueDate || '').trim();
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (!match) return '';
  const [, year, month, day] = match;
  const date = new Date(Date.UTC(Number(year), Number(month) - 1, Number(day)));
  date.setUTCDate(date.getUTCDate() + Math.max(0, whole(validDays, 30)));
  return date.toISOString().slice(0, 10);
};

const canonicalAcceptance = (rows: any[] = []) => rows.slice().sort((a, b) => {
  const aTime = Date.parse(a?.created_date || a?.accepted_at || '') || 0;
  const bTime = Date.parse(b?.created_date || b?.accepted_at || '') || 0;
  if (aTime !== bTime) return aTime - bTime;
  return String(a?.id || '').localeCompare(String(b?.id || ''));
})[0] || null;

// A superseded acceptance stays in the audit trail but no longer counts as the
// canonical approval for its quote version — dedupe/convergence checks run on
// active rows only so a fresh acceptance can be recorded after a supersede.
const isActiveAcceptance = (row: any) =>
  String(row?.status || 'accepted') !== 'superseded' && !row?.superseded_at;
const activeAcceptanceRows = (rows: any[] = []) => (Array.isArray(rows) ? rows : []).filter(isActiveAcceptance);

// Mirror the canonical acceptance onto the Estimate record itself so
// accepted_at/accepted_by_* is queryable without joining EstimateAcceptance.
// CAS on the loaded updated_date; failures never fail the acceptance write.
async function patchEstimateAcceptanceFields(Estimate: any, estimateId: string, estimate: any, acceptance: any) {
  if (!acceptance?.id) return;
  const patch = {
    accepted_at: String(acceptance.accepted_at || '').trim() || new Date().toISOString(),
    accepted_by_name: String(acceptance.accepted_by_name || '').trim(),
    accepted_by_email: String(acceptance.accepted_by_email || '').trim(),
  };
  const filter: any = { id: estimateId };
  const version = String(estimate?.updated_date || '').trim();
  if (version) filter.updated_date = version;
  try {
    await Estimate.updateMany(filter, { $set: patch });
  } catch (e: any) {
    console.error('Estimate acceptance field mirror failed:', e?.message || e);
  }
}

/**
 * (#255) Staff-side "reject quote": CAS the estimate to cancelled (the state the
 * codebase treats as customer-lost — the pipeline maps it to `lost`, mirroring
 * the portal decline path and the Cancel Estimate modal's cancelled_at /
 * cancel_reason fields) and queue an idempotent `ready` EstimatingRequest
 * follow-up assigned to the estimate owner with a due date. CAS-anchored on the
 * estimate's updated_date; retries converge instead of double-writing.
 */
async function rejectEstimateQuote({ base44, user, body }: any) {
  const Estimate = base44.asServiceRole.entities.AllInOneEstimate;
  const EstimatingRequest = base44.asServiceRole.entities.EstimatingRequest;
  const estimateId = String(body?.estimate_id || '').trim();
  const reason = String(body?.reason || '').trim().slice(0, 500);
  if (!estimateId) {
    return Response.json({ error: 'Estimate is required to reject a quote.' }, { status: 400 });
  }
  if (!reason) {
    return Response.json({ error: 'A rejection reason is required — a lost quote must never be silent.' }, { status: 400 });
  }
  const rawDueDate = String(body?.due_date || '').trim();
  const dueDate = /^\d{4}-\d{2}-\d{2}$/.test(rawDueDate)
    ? rawDueDate
    : new Date(Date.now() + 2 * 86400000).toISOString().slice(0, 10);
  const expectedVersion = String(body?.expected_estimate_updated_date || '').trim();

  const estimate = await Estimate.get(estimateId).catch(() => null);
  if (!estimate?.id || estimate?.deleted === true) {
    return Response.json({ error: 'Estimate could not be verified for quote rejection.' }, { status: 404 });
  }
  if (expectedVersion && expectedVersion !== String(estimate.updated_date || '').trim()) {
    return Response.json({ error: 'This estimate changed in another session. Reload before rejecting the quote.' }, { status: 409 });
  }
  if (String(estimate.work_order_id || '').trim()) {
    return Response.json({ error: 'This estimate is already linked to a Work Order. Cancel or close the job from the workflow instead of rejecting its source quote.' }, { status: 409 });
  }

  const status = String(estimate.status || '').trim();
  let saved = estimate;
  let reused = false;
  if (status === 'sent') {
    const anchor = String(estimate.updated_date || '').trim();
    if (!anchor) {
      return Response.json({ error: 'Estimate is missing version metadata and cannot be rejected safely.' }, { status: 409 });
    }
    const result = await Estimate.updateMany(
      { id: estimateId, updated_date: anchor },
      { $set: { status: 'cancelled', cancel_reason: reason, cancelled_at: new Date().toISOString(), edit_reason: '' } },
    );
    if (!result || typeof result.updated !== 'number') {
      throw new Error('Quote rejection conditional-update result could not be verified.');
    }
    if (result.updated !== 1) {
      // CAS lost the race — converge only when the row already reflects THIS
      // rejection (same reason), never paper over a different transition.
      const after = await Estimate.get(estimateId).catch(() => null);
      if (after?.id && String(after?.status || '') === 'cancelled' && String(after?.cancel_reason || '').trim() === reason) {
        saved = after;
        reused = true;
      } else {
        return Response.json({ error: 'Estimate changed while the quote was being rejected. Reload before rejecting again.' }, { status: 409 });
      }
    } else {
      saved = await Estimate.get(estimateId).catch(() => null) || estimate;
    }
  } else if (status === 'cancelled' && String(estimate.cancel_reason || '').trim() === reason) {
    // Replay of this exact rejection — the estimate is already cancelled;
    // converge on the follow-up task below.
    reused = true;
  } else {
    return Response.json({ error: `This quote is ${status || 'not awaiting response'} — only sent quotes can be rejected.` }, { status: 409 });
  }

  // Staff follow-up task: an idempotent queue-visible EstimatingRequest puts
  // the loss on the estimator queue assigned to the estimate owner with a due
  // date (mirrors the portal decline's `ready` follow-up row convention).
  let followUp: any = null;
  let followUpWarning = '';
  const requestKey = `staff-reject-request:${estimateId}`;
  const quoteVersion = Math.max(0, whole(estimate.quote_version));
  const quoteLabel = `Quote Version ${quoteVersion || '?'}${estimate.estimate_number ? ` · ${estimate.estimate_number}` : ''}`;
  try {
    const projectName = String(estimate.project_name || estimate.estimate_number || 'estimate').trim();
    const created = await createFoundationRecordWithRecovery({
      entity: EstimatingRequest,
      data: {
        creation_request_key: requestKey,
        estimate_id: estimateId,
        opportunity_id: String(estimate.opportunity_id || '').trim() || `staff-reject:${estimateId}`,
        customer_id: String(estimate.customer_id || '').trim(),
        // "ready" is the queue-visible status — it lands on the estimator
        // queue and attention feed, unlike the legacy "open" value.
        status: 'ready',
        requested_at: new Date().toISOString(),
        submitted_at: new Date().toISOString(),
        requested_by: String(user.email || user.full_name || user.name || 'staff').trim(),
        assigned_estimator: String(estimate.salesperson_email || estimate.created_by || estimate.salesperson || '').trim(),
        due_date: dueDate,
        priority: 'high',
        request_kind: 'quote_rejection_followup',
        request_notes: `Staff rejected ${quoteLabel} on ${projectName}: ${reason.slice(0, 400)} — follow up with the customer.`,
      },
      readMatches: () => EstimatingRequest.filter({ creation_request_key: requestKey }),
      label: 'Staff quote rejection follow-up task',
    });
    followUp = created?.record || null;
  } catch (error: any) {
    // The rejection itself is durable — a queue failure is surfaced, never
    // silently rolled back or fatal (mirrors the portal decline convention).
    console.error('Quote rejected but its follow-up task failed:', error?.message || error);
    followUpWarning = 'The quote was rejected, but its estimator follow-up task could not be queued. Create the follow-up manually.';
  }

  return Response.json({ success: true, action: 'reject_quote', estimate: saved, follow_up: followUp, follow_up_warning: followUpWarning, reused });
}

/**
 * (#271) Supersede acceptance: mark the canonical EstimateAcceptance row for
 * the current Quote Version as superseded (additive status/superseded_* audit
 * fields, CAS on the row's own updated_date) and CAS the estimate from
 * Approved back to Sent (needs-resend) with the acceptance mirror fields
 * cleared. The lifecycle EstimateRevision is written by the caller through
 * the normal guarded path. Retries converge on either half.
 */
async function supersedeEstimateAcceptance({ base44, user, body }: any) {
  const Estimate = base44.asServiceRole.entities.AllInOneEstimate;
  const Acceptance = base44.asServiceRole.entities.EstimateAcceptance;
  const estimateId = String(body?.estimate_id || '').trim();
  const acceptanceId = String(body?.acceptance_id || '').trim();
  const reason = String(body?.reason || '').trim().slice(0, 500) || 'Customer acceptance superseded by staff.';
  const expectedVersion = String(body?.expected_estimate_updated_date || '').trim();
  if (!estimateId) {
    return Response.json({ error: 'Estimate is required to supersede an acceptance.' }, { status: 400 });
  }

  const estimate = await Estimate.get(estimateId).catch(() => null);
  if (!estimate?.id || estimate?.deleted === true) {
    return Response.json({ error: 'Estimate could not be verified for acceptance supersede.' }, { status: 404 });
  }
  if (expectedVersion && expectedVersion !== String(estimate.updated_date || '').trim()) {
    return Response.json({ error: 'This estimate changed in another session. Reload before superseding the acceptance.' }, { status: 409 });
  }
  const status = String(estimate.status || '').trim();
  if (!['approved', 'sent'].includes(status)) {
    return Response.json({ error: `Only an Approved estimate's customer acceptance can be superseded.` }, { status: 409 });
  }
  const quoteVersion = Math.max(0, whole(estimate.quote_version));
  const rows = await Acceptance.filter({ estimate_id: estimateId, quote_version: quoteVersion });
  if (!Array.isArray(rows)) {
    throw new Error('Acceptance history could not be verified safely.');
  }
  const activeRows = activeAcceptanceRows(rows);
  const target = (acceptanceId ? activeRows.find((row: any) => String(row?.id || '') === acceptanceId) : null)
    || canonicalAcceptance(activeRows);
  if (!target?.id) {
    return Response.json({ error: 'No active customer acceptance exists for the current Quote Version.' }, { status: 409 });
  }

  // Return the estimate to Sent (the needs-resend state) first; the mirror
  // fields are cleared so lists stop showing the stale customer approval.
  let saved = estimate;
  let reused = false;
  if (status === 'approved') {
    const anchor = String(estimate.updated_date || '').trim();
    if (!anchor) {
      return Response.json({ error: 'Estimate is missing version metadata and cannot be superseded safely.' }, { status: 409 });
    }
    const result = await Estimate.updateMany(
      { id: estimateId, updated_date: anchor },
      { $set: { status: 'sent', accepted_at: '', accepted_by_name: '', accepted_by_email: '', edit_reason: '' } },
    );
    if (!result || typeof result.updated !== 'number') {
      throw new Error('Acceptance supersede conditional-update result could not be verified.');
    }
    if (result.updated !== 1) {
      const after = await Estimate.get(estimateId).catch(() => null);
      if (after?.id && String(after?.status || '') === 'sent') {
        saved = after;
        reused = true;
      } else {
        return Response.json({ error: 'Estimate changed while the acceptance was being superseded. Reload before superseding again.' }, { status: 409 });
      }
    } else {
      saved = await Estimate.get(estimateId).catch(() => null) || estimate;
    }
  } else {
    // Already Sent — a prior attempt CAS'd the estimate before failing on the
    // acceptance mark; converge on the acceptance update below.
    reused = true;
  }

  const targetVersion = String(target.updated_date || '').trim();
  if (!targetVersion) {
    throw new Error('The acceptance record is missing version metadata and cannot be superseded safely.');
  }
  const patch = {
    status: 'superseded',
    superseded_at: new Date().toISOString(),
    superseded_by_email: String(user.email || '').trim(),
    superseded_by_name: String(user.full_name || user.name || user.email || '').trim(),
    supersede_reason: reason,
  };
  const result = await Acceptance.updateMany({ id: target.id, updated_date: targetVersion }, { $set: patch });
  if (!result || typeof result.updated !== 'number') {
    throw new Error('Acceptance supersede conditional-update result could not be verified.');
  }
  let superseded: any = target;
  if (result.updated === 1) {
    superseded = await Acceptance.get(target.id).catch(() => null) || { ...target, ...patch };
  } else {
    const after = await Acceptance.get(target.id).catch(() => null);
    if (after?.id && !isActiveAcceptance(after)) {
      superseded = after;
      reused = true;
    } else {
      return Response.json({ error: 'Acceptance changed while it was being superseded. Reload before superseding again.' }, { status: 409 });
    }
  }

  return Response.json({ success: true, action: 'supersede_acceptance', estimate: saved, acceptance: superseded, reused });
}

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const body = await req.json().catch(() => ({}));
    const user = await authenticateSignShopSession(base44, body?.session_token);
    const action = String(body?.action || 'record').trim();
    if (action === 'reject_quote') return await rejectEstimateQuote({ base44, user, body });
    if (action === 'supersede_acceptance') return await supersedeEstimateAcceptance({ base44, user, body });
    const estimateId = String(body?.estimate_id || '').trim();
    const quoteVersion = Math.max(0, whole(body?.quote_version));
    const acceptedByName = String(body?.accepted_by_name || '').trim();
    const acceptedByEmail = String(body?.accepted_by_email || '').trim();
    if (acceptedByEmail && !/^[^@ ]+@[^@ ]+[.][^@ ]+$/.test(acceptedByEmail)) {
      return Response.json({ error: 'accepted_by_email is not a valid email address.' }, { status: 400 });
    }
    const acceptanceMethod = String(body?.acceptance_method || '').trim();
    const acceptedAt = String(body?.accepted_at || '').trim();
    const deliveryId = String(body?.delivery_id || '').trim();
    const rawEvidence = String(body?.evidence_reference || '').trim();
    // evidence_reference is free text (PO number, "signed quote", etc.), but a
    // javascript:/data:/vbscript: scheme must never be persisted as a reference.
    const evidenceReference = /^(javascript|data|vbscript)[ ]*:/i.test(rawEvidence) ? '' : rawEvidence;
    const notes = String(body?.notes || '').trim();

    if (!estimateId || quoteVersion <= 0) {
      return Response.json({ error: 'Estimate id and issued Quote Version are required.' }, { status: 400 });
    }
    if (!acceptedAt || !METHODS.has(acceptanceMethod)) {
      return Response.json({ error: 'Acceptance date/time and a valid acceptance method are required.' }, { status: 400 });
    }
    if (!Number.isFinite(Date.parse(acceptedAt))) {
      return Response.json({ error: 'Acceptance date/time is invalid.' }, { status: 400 });
    }
    const acceptedMs = Date.parse(acceptedAt);
    const nowMs = Date.now();
    if (acceptedMs > nowMs + 15 * 60 * 1000) {
      return Response.json({ error: 'Acceptance date/time cannot be in the future.' }, { status: 400 });
    }
    if (acceptedMs < nowMs - 10 * 365 * 24 * 60 * 60 * 1000) {
      return Response.json({ error: 'Acceptance date/time is unreasonably old.' }, { status: 400 });
    }

    const Estimate = base44.asServiceRole.entities.AllInOneEstimate;
    const Acceptance = base44.asServiceRole.entities.EstimateAcceptance;
    const Delivery = base44.asServiceRole.entities.EstimateQuoteDelivery;

    const estimate = await Estimate.get(estimateId);
    if (!estimate || !['sent', 'approved'].includes(String(estimate.status || ''))) {
      return Response.json({ error: 'Customer acceptance can only be recorded for a Sent or Approved estimate.' }, { status: 409 });
    }
    const currentVersion = Math.max(0, whole(estimate.quote_version));
    if (!currentVersion || currentVersion !== quoteVersion) {
      return Response.json({ error: 'The issued Quote Version changed. Reload the estimate before recording acceptance.' }, { status: 409 });
    }
    // Expired-quote gate: acceptance is disabled once the quote's validity
    // window has passed — issue a revised quote (new quote_version) instead.
    const expirationDate = quoteExpirationDate(estimate.quote_issue_date, estimate.quote_valid_days ?? 30);
    if (expirationDate && expirationDate < new Date().toISOString().slice(0, 10)) {
      return Response.json({ error: 'This quote is expired. Issue a revised quote before recording acceptance.' }, { status: 409 });
    }
    // accepted_by fallback: when the caller omits the name, resolve it from the
    // estimate's customer contact (first+last, then order_contact/contact_name).
    const resolvedByName = acceptedByName
      || [estimate.contact_first_name, estimate.contact_last_name].map((v: any) => String(v || '').trim()).filter(Boolean).join(' ')
      || String(estimate.order_contact || estimate.contact_name || '').trim();
    if (!resolvedByName) {
      return Response.json({ error: 'Accepted by is required and no customer contact name is on file.' }, { status: 400 });
    }

    // Dedupe/convergence considers ACTIVE acceptances only — a superseded row
    // must not block a fresh acceptance on the same quote version.
    const existingRowsRaw = await Acceptance.filter({
      estimate_id: estimateId,
      quote_version: quoteVersion,
    });
    if (!Array.isArray(existingRowsRaw)) {
      throw new Error('Acceptance history could not be verified safely.');
    }
    const existingRows = activeAcceptanceRows(existingRowsRaw);
    if (existingRows.length > 1) {
      throw new Error('Multiple immutable acceptance records already exist for this Quote Version. No acceptance was changed; review the acceptance history before continuing.');
    }
    const existing = canonicalAcceptance(existingRows);
    if (existing) {
      await patchEstimateAcceptanceFields(Estimate, estimateId, estimate, existing);
      return Response.json({ acceptance: existing, reused: true });
    }
    if (estimate.status === 'approved') {
      return Response.json({ error: 'This estimate is already Approved, but no immutable acceptance record exists for the current Quote Version. Acceptance cannot be reconstructed automatically.' }, { status: 409 });
    }

    let delivery: any = null;
    if (deliveryId) {
      delivery = await Delivery.get(deliveryId);
      if (
        !delivery ||
        delivery.estimate_id !== estimateId ||
        Math.max(0, whole(delivery.quote_version)) !== quoteVersion ||
        delivery.delivery_status !== 'sent'
      ) {
        return Response.json({ error: 'The selected quote delivery does not belong to this estimate/version.' }, { status: 409 });
      }
    }

    let created: any = null;
    let createError: any = null;
    try {
      created = await Acceptance.create({
        estimate_id: estimateId,
        work_order_id: estimate.work_order_id || '',
        delivery_id: delivery?.id || '',
        quote_issue_key: quoteIssueKey(estimateId, quoteVersion),
        quote_version: quoteVersion,
        quote_issue_date: estimate.quote_issue_date || '',
        quote_expiration_date: quoteExpirationDate(estimate.quote_issue_date, estimate.quote_valid_days ?? 30),
        quote_total: Number(estimate.quote_total || 0),
        accepted_at: new Date(acceptedAt).toISOString(),
        accepted_by_name: resolvedByName,
        accepted_by_email: acceptedByEmail,
        acceptance_method: acceptanceMethod,
        evidence_reference: evidenceReference,
        notes,
        recorded_by_email: String(user.email || ''),
        recorded_by_name: String(user.full_name || user.name || user.email || ''),
      });
    } catch (error) {
      createError = error;
    }

    // Re-read after create to collapse the practical two-session race without
    // requiring unsupported database unique-index behavior. Only this request's
    // losing insert is removed; an already-canonical immutable row is never edited.
    await new Promise((resolve) => setTimeout(resolve, 50));
    const afterCreateRowsRaw = await Acceptance.filter({
      estimate_id: estimateId,
      quote_version: quoteVersion,
    });
    if (!Array.isArray(afterCreateRowsRaw)) {
      throw new Error('Acceptance create outcome could not be verified safely.');
    }
    const afterCreateRows = activeAcceptanceRows(afterCreateRowsRaw);
    if (!created?.id) {
      if (afterCreateRows.length === 1) {
        await patchEstimateAcceptanceFields(Estimate, estimateId, estimate, afterCreateRows[0]);
        return Response.json({ acceptance: afterCreateRows[0], reused: true, recovered_after_create_error: true });
      }
      if (afterCreateRows.length > 1) {
        throw new Error('Acceptance creation became ambiguous and multiple immutable records are now visible. No uncertain acceptance was deleted; review the acceptance history before retrying.');
      }
      throw createError || new Error('Acceptance could not be created or verified.');
    }

    const canonical = canonicalAcceptance(afterCreateRows) || created;

    if (afterCreateRows.length > 1 && canonical?.id === created.id) {
      throw new Error('A concurrent acceptance record was detected after this acceptance was created. The earlier canonical row was preserved and no uncertain concurrent record was deleted; review the acceptance history before continuing.');
    }

    if (canonical?.id && created?.id && canonical.id !== created.id) {
      const createdVersion = String(created.updated_date || '').trim();
      if (!createdVersion) {
        throw new Error('A duplicate acceptance record was detected, but the losing row has no version metadata. No uncertain acceptance was deleted.');
      }
      const deleted = await Acceptance.deleteMany({
        id: created.id,
        estimate_id: estimateId,
        quote_version: quoteVersion,
        updated_date: createdVersion,
      });
      if (!deleted || deleted.deleted !== 1) {
        throw new Error('A duplicate acceptance record changed before cleanup. No uncertain acceptance was deleted; reload the acceptance history before retrying.');
      }
      // Mirror the canonical (earliest-created) acceptance, not the duplicate
      // this request is about to discard — the estimate must reflect the row
      // that actually survives dedupe.
      await patchEstimateAcceptanceFields(Estimate, estimateId, estimate, canonical);
      return Response.json({ acceptance: canonical, reused: true, concurrent_duplicate_discarded: true });
    }

    // Notify the estimate owner (salesperson) that the customer accepted —
    // fire-and-forget so a Gmail outage never blocks the acceptance write.
    try {
      const ownerEmail = String(estimate.created_by || estimate.salesperson_email || '').trim();
      if (ownerEmail && ownerEmail !== String(user.email || '').trim()) {
        const projectName = String(estimate.project_name || estimate.estimate_number || 'estimate').trim();
        await base44.asServiceRole.functions.invoke('sendGmail', {
          to: ownerEmail,
          subject: `Quote accepted: ${projectName}`,
          body: `${acceptedByName} accepted quote version ${quoteVersion} on ${projectName}

Total: $${Number(estimate.quote_total || 0).toFixed(2)}
Method: ${acceptanceMethod}
${notes ? `Notes: ${notes}` : ''}`.trim(),
          _workflow_capability: 'ccs-sendGmail-acceptance-notify',
        });
      }
    } catch (notifyError) {
      console.error('Acceptance salesperson notify failed:', notifyError?.message || notifyError);
    }
    // Confirmation to the customer that their acceptance was recorded —
    // same fire-and-forget pattern; a Gmail outage never blocks the write.
    try {
      if (acceptedByEmail) {
        const custProject = String(estimate.project_name || estimate.estimate_number || 'your estimate').trim();
        await base44.asServiceRole.functions.invoke('sendGmail', {
          to: acceptedByEmail,
          subject: `Quote acceptance confirmed: ${custProject}`,
          body: `Thank you${acceptedByName ? `, ${acceptedByName}` : ''} — your approval of quote version ${quoteVersion} for ${custProject} ($${Number(estimate.quote_total || 0).toFixed(2)}) has been recorded. We'll be in touch about next steps.`,
          _workflow_capability: 'ccs-sendGmail-acceptance-confirm',
        });
      }
    } catch (confirmError) {
      console.error('Acceptance customer confirm failed:', confirmError?.message || confirmError);
    }
    await patchEstimateAcceptanceFields(Estimate, estimateId, estimate, canonical);
    return Response.json({ acceptance: canonical, reused: false });
  } catch (error) {
    const status = Number(error?.status || 500);
    const safeStatus = [400, 401, 409, 429, 503].includes(status) ? status : 500;
    console.error('recordEstimateAcceptance error:', error?.message || error);
    return Response.json({
      error: safeStatus === 500 ? 'Customer acceptance could not be recorded safely.' : error.message,
    }, { status: safeStatus });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';
import { estimateQuoteIssueKey } from '../../shared/estimateRevisionAudit.ts';
import { createFoundationRecordWithRecovery } from '../../shared/opportunityFoundationPersistence.mjs';
import { ensureQuoteRecipientContact } from '../../shared/quoteRecipientContact.mjs';

const MAX_TEXT = 1000;
const MAX_URL = 4096;

const whole = (value: unknown, fallback = 0) => {
  const parsed = Math.floor(Number(value));
  return Number.isFinite(parsed) ? parsed : fallback;
};

const cleanText = (value: unknown, max = MAX_TEXT) => String(value || '').trim().slice(0, max);

const safeUrl = (value: unknown, max = MAX_URL) => {
  const raw = cleanText(value, max);
  if (!raw) return '';
  try {
    const url = new URL(raw);
    return ['https:'].includes(url.protocol) ? url.toString().slice(0, max) : '';
  } catch {
    return '';
  }
};

const canonicalDelivery = (rows: any[] = []) => rows.slice().sort((a, b) => {
  const aTime = Date.parse(a?.created_date || a?.sent_at || '') || 0;
  const bTime = Date.parse(b?.created_date || b?.sent_at || '') || 0;
  if (aTime !== bTime) return aTime - bTime;
  return String(a?.id || '').localeCompare(String(b?.id || ''));
})[0] || null;

function sameDelivery(row: any, data: any) {
  return String(row?.estimate_id || '') === String(data?.estimate_id || '') &&
    whole(row?.quote_version) === whole(data?.quote_version) &&
    String(row?.recipient_email || '').trim().toLowerCase() === String(data?.recipient_email || '').trim().toLowerCase() &&
    String(row?.gmail_message_id || '') === String(data?.gmail_message_id || '') &&
    String(row?.attachment_sha256 || '').toLowerCase() === String(data?.attachment_sha256 || '').toLowerCase();
}

// Delivery telemetry boundary (#246/#296): this audit records send-time
// outcome only (accepted by transport vs send attempt failed). Neither the
// Gmail API transport nor the SMTP transport exposes a webhook/bounce channel
// to this app, so post-send delivery/bounce data is genuinely unavailable.
const DELIVERY_TELEMETRY_NOTE = 'Send-time outcome only — provider webhook/bounce telemetry is unavailable on this transport.';

const QUOTE_APPROVAL_THRESHOLD_KEY = 'quote_approval_threshold';
const DEFAULT_QUOTE_APPROVAL_THRESHOLD = 5000;
const QUOTE_APPROVAL_REQUIRED_MESSAGE = 'This quote exceeds the internal approval threshold â€” a manager must approve it before sending.';

const money = (value: unknown, fallback = 0) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
};

async function loadQuoteApprovalThreshold(Settings: any) {
  const rows = await Settings.filter({ setting_key: QUOTE_APPROVAL_THRESHOLD_KEY });
  if (!Array.isArray(rows)) throw new Error('Quote approval threshold setting could not be verified.');
  const raw = rows[0]?.setting_value;
  const parsed = Number(raw?.threshold ?? raw?.value ?? raw);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : DEFAULT_QUOTE_APPROVAL_THRESHOLD;
}

function recordedQuoteApproval(estimate: any) {
  const approval = estimate?.internal_approval;
  if (!approval || typeof approval !== 'object' || Array.isArray(approval)) return null;
  if (!approval.approved_at && !approval.approved_by_email && !approval.approved_by_user_id) return null;
  return approval;
}

function quoteApprovalCovers(estimate: any, quoteTotal: number) {
  const approval = recordedQuoteApproval(estimate);
  if (!approval) return false;
  // An approval recorded at a lower total does not cover a larger quote; the
  // quote needs a fresh approval if its total grew past the approved amount.
  const approvedTotal = Number(approval?.quote_total_at_approval);
  if (Number.isFinite(approvedTotal) && approvedTotal > 0 && quoteTotal > approvedTotal + 0.005) return false;
  return true;
}

async function assertQuoteSendAuthorized({ Settings, estimate, quoteTotal, user }: any) {
  const threshold = await loadQuoteApprovalThreshold(Settings);
  if (!(quoteTotal > threshold)) return { threshold, required: false };
  if (user?.can_approve_quotes === true) return { threshold, required: true, manager_bypass: true };
  if (quoteApprovalCovers(estimate, quoteTotal)) {
    return { threshold, required: true, approval: estimate.internal_approval };
  }
  throw Object.assign(new Error(QUOTE_APPROVAL_REQUIRED_MESSAGE), { status: 403 });
}

async function approveEstimateQuote({ Estimate, Settings, user, body }: any) {
  if (user?.can_approve_quotes !== true) {
    return Response.json({ error: 'This account is not authorized to approve customer quotes.' }, { status: 403 });
  }
  const estimateId = cleanText(body?.estimate_id, 128);
  if (!estimateId) {
    return Response.json({ error: 'Estimate is required for quote approval.' }, { status: 400 });
  }
  const estimate = await Estimate.get(estimateId).catch(() => null);
  if (!estimate?.id) {
    return Response.json({ error: 'Estimate could not be verified for quote approval.' }, { status: 404 });
  }
  const threshold = await loadQuoteApprovalThreshold(Settings);
  const quoteTotal = Math.max(money(body?.quote_total), money(estimate.quote_total));
  if (quoteApprovalCovers(estimate, quoteTotal)) {
    return Response.json({ success: true, estimate_id: estimate.id, internal_approval: estimate.internal_approval, reused: true });
  }
  const approval = {
    approved_by_user_id: String(user.id || ''),
    approved_by_email: String(user.email || '').trim().toLowerCase(),
    approved_at: new Date().toISOString(),
    threshold_at_approval: threshold,
    quote_total_at_approval: quoteTotal,
    quote_version: Math.max(0, whole(estimate.quote_version)),
  };
  const expectedVersion = String(estimate.updated_date || '').trim();
  if (!expectedVersion) {
    return Response.json({ error: 'Estimate is missing version metadata and cannot be approved safely.' }, { status: 409 });
  }
  const result = await Estimate.updateMany(
    { id: estimate.id, updated_date: expectedVersion },
    { $set: { internal_approval: approval } },
  );
  if (!result || typeof result.updated !== 'number') {
    throw new Error('Quote approval conditional-update result could not be verified.');
  }
  if (result.updated !== 1) {
    // The estimate changed between the read and the CAS write. If a concurrent
    // manager already recorded a covering approval, adopt it; otherwise make
    // the conflict explicit so a stale session never silently double-approves.
    const after = await Estimate.get(estimate.id).catch(() => null);
    if (after?.id && quoteApprovalCovers(after, quoteTotal)) {
      return Response.json({ success: true, estimate_id: estimate.id, internal_approval: after.internal_approval, reused: true });
    }
    return Response.json({ error: 'Estimate changed while the approval was being recorded. Reload before approving again.' }, { status: 409 });
  }
  const saved = await Estimate.get(estimate.id).catch(() => null);
  if (String(saved?.internal_approval?.approved_at || '') !== approval.approved_at) {
    throw new Error('Quote approval was written but could not be verified.');
  }
  return Response.json({ success: true, estimate_id: estimate.id, internal_approval: approval });
}

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const body = await req.json().catch(() => ({}));
    const user = await authenticateSignShopSession(base44, body?.session_token);

    const Estimate = base44.asServiceRole.entities.AllInOneEstimate;
    const Settings = base44.asServiceRole.entities.GlobalSettings;
    const action = cleanText(body?.action, 64);

    if (action === 'approve_quote') {
      return await approveEstimateQuote({ Estimate, Settings, user, body });
    }
    if (action === 'authorize_send') {
      const authorizeEstimateId = cleanText(body?.estimate_id, 128);
      if (!authorizeEstimateId) {
        return Response.json({ error: 'Estimate is required for send authorization.' }, { status: 400 });
      }
      const authorizeEstimate = await Estimate.get(authorizeEstimateId).catch(() => null);
      if (!authorizeEstimate?.id) {
        return Response.json({ error: 'Estimate could not be verified for quote sending.' }, { status: 404 });
      }
      const authorizeTotal = Math.max(money(body?.quote_total), money(authorizeEstimate.quote_total));
      const gate = await assertQuoteSendAuthorized({ Settings, estimate: authorizeEstimate, quoteTotal: authorizeTotal, user });
      return Response.json({ success: true, allowed: true, ...gate, internal_approval: recordedQuoteApproval(authorizeEstimate) });
    }

    const input = body?.delivery && typeof body.delivery === 'object' ? body.delivery : {};
    const estimateId = cleanText(input.estimate_id, 128);
    const quoteVersion = Math.max(0, whole(input.quote_version));
    const recipientEmail = cleanText(input.recipient_email, 320).toLowerCase();
    const gmailMessageId = cleanText(input.gmail_message_id, 512);
    const attachmentSha256 = cleanText(input.attachment_sha256, 128).toLowerCase();
    const sentAt = cleanText(input.sent_at, 64);
    const deliveryOutcome = cleanText(input.delivery_status, 32) === 'failed' ? 'failed' : 'sent';
    const failureReason = cleanText(input.failure_reason, 500);
    const transport = cleanText(input.transport, 40) || 'gmail_api';

    if (!estimateId || !recipientEmail || !sentAt) {
      return Response.json({ error: 'Estimate, recipient, and sent timestamp are required.' }, { status: 400 });
    }
    if (deliveryOutcome === 'sent' && !gmailMessageId) {
      return Response.json({ error: 'Estimate, recipient, Gmail message id, and sent timestamp are required.' }, { status: 400 });
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipientEmail)) {
      return Response.json({ error: 'Quote delivery recipient email is invalid.' }, { status: 400 });
    }
    if (!Number.isFinite(Date.parse(sentAt))) {
      return Response.json({ error: 'Quote delivery sent timestamp is invalid.' }, { status: 400 });
    }
    if (attachmentSha256 && !/^[a-f0-9]{64}$/.test(attachmentSha256)) {
      return Response.json({ error: 'Quote delivery PDF fingerprint is invalid.' }, { status: 400 });
    }

    const Delivery = base44.asServiceRole.entities.EstimateQuoteDelivery;
    const CustomerContact = base44.asServiceRole.entities.CustomerContact;
    const estimate = await Estimate.get(estimateId).catch(() => null);
    if (!estimate?.id) {
      return Response.json({ error: 'Estimate could not be verified for quote delivery history.' }, { status: 404 });
    }
    // The recorded delivery must describe the estimate's current issued quote â€”
    // an arbitrary version or foreign work order would let a session forge the
    // immutable delivery/audit trail.
    const issuedVersion = Math.max(0, whole(estimate.quote_version));
    if (!quoteVersion || quoteVersion !== issuedVersion) {
      return Response.json({ error: 'Quote delivery does not match the issued quote version.' }, { status: 409 });
    }
    const claimedWo = cleanText(input.work_order_id, 128);
    if (claimedWo && String(estimate.work_order_id || '') !== claimedWo) {
      return Response.json({ error: 'Quote delivery work order does not match the estimate.' }, { status: 409 });
    }

    // Failed send attempts are immutable audit rows too (#246/#296): no
    // Gmail message id exists, so attempts dedupe on attempt_key/sent_at and
    // skip the send-authorization backstop (the send already failed — this
    // write only records that outcome; it never marks anything sent).
    if (deliveryOutcome === 'failed') {
      const attemptKey = `quote_delivery_attempt:${estimateId}:${quoteVersion}:${cleanText(input.attempt_key, 120) || `${recipientEmail}:${sentAt}`}`;
      const existingAttempts = await Delivery.filter({ idempotency_key: attemptKey }).catch(() => []);
      if (Array.isArray(existingAttempts) && existingAttempts.length) {
        return Response.json({ delivery: existingAttempts[0], reused: true });
      }
      const priorAttempts = await Delivery.filter({ quote_issue_key: estimateQuoteIssueKey(estimateId, quoteVersion) }).catch(() => []);
      const attemptRow = {
        estimate_id: estimateId,
        idempotency_key: attemptKey,
        work_order_id: cleanText(estimate.work_order_id || input.work_order_id, 128),
        quote_issue_key: estimateQuoteIssueKey(estimateId, quoteVersion),
        quote_version: quoteVersion,
        quote_issue_date: cleanText(input.quote_issue_date, 32),
        quote_valid_days: Math.max(0, whole(input.quote_valid_days, 30)),
        quote_expiration_date: cleanText(input.quote_expiration_date, 32),
        quote_total: Number.isFinite(Number(input.quote_total)) ? Number(input.quote_total) : 0,
        recipient_email: recipientEmail,
        cc_emails: cleanText(input.cc_emails, 998),
        bcc_emails: cleanText(input.bcc_emails, 998),
        subject: cleanText(input.subject, 998),
        delivery_method: 'email',
        delivery_status: 'failed',
        sent_at: new Date(sentAt).toISOString(),
        gmail_message_id: '',
        attachment_filename: cleanText(input.attachment_filename, 255),
        is_resend: input.is_resend === true,
        delivery_n: (Array.isArray(priorAttempts) ? priorAttempts.filter((r: any) => r?.deleted !== true).length : 0) + 1,
        source_status: cleanText(input.source_status, 64),
        transport,
        failure_reason: failureReason || 'send failed',
        delivery_events: [{ at: new Date(sentAt).toISOString(), outcome: 'failed', transport, detail: failureReason || 'send failed' }],
        telemetry_note: DELIVERY_TELEMETRY_NOTE,
      };
      let createAttemptError = "";
      const createdAttempt = await Delivery.create(attemptRow).catch((e: any) => { createAttemptError = String(e?.message || e); return null; });
      await new Promise((resolve) => setTimeout(resolve, 50));
      const verifyAttempts = await Delivery.filter({ idempotency_key: attemptKey }).catch(() => []);
      const attempt = createdAttempt?.id ? createdAttempt : (Array.isArray(verifyAttempts) ? verifyAttempts[0] : null);
      if (!attempt?.id) {
        throw new Error(`Quote delivery attempt audit could not be created or verified.${createAttemptError ? ` ${createAttemptError}` : ""}`);
      }
      return Response.json({ delivery: attempt, attempted: true, reused: !createdAttempt?.id });
    }

    const idempotencyKey = `quote_delivery:gmail:${gmailMessageId}`;
    const normalized = {
      estimate_id: estimateId,
      idempotency_key: idempotencyKey,
      work_order_id: cleanText(estimate.work_order_id || input.work_order_id, 128),
      quote_issue_key: estimateQuoteIssueKey(estimateId, quoteVersion),
      quote_version: quoteVersion,
      quote_issue_date: cleanText(input.quote_issue_date, 32),
      quote_valid_days: Math.max(0, whole(input.quote_valid_days, 30)),
      quote_expiration_date: cleanText(input.quote_expiration_date, 32),
      quote_total: Number.isFinite(Number(input.quote_total)) ? Number(input.quote_total) : 0,
      recipient_email: recipientEmail,
      cc_emails: cleanText(input.cc_emails, 998),
      bcc_emails: cleanText(input.bcc_emails, 998),
      subject: cleanText(input.subject, 998),
      delivery_method: 'email',
      delivery_status: 'sent',
      sent_at: new Date(sentAt).toISOString(),
      gmail_message_id: gmailMessageId,
      attachment_filename: cleanText(input.attachment_filename, 255),
      attachment_file_url: safeUrl(input.attachment_file_url),
      attachment_sha256: attachmentSha256,
      attachment_size_bytes: Math.max(0, whole(input.attachment_size_bytes)),
      is_resend: input.is_resend === true,
      source_status: cleanText(input.source_status, 64),
      transport,
      failure_reason: '',
      delivery_events: [{ at: new Date(sentAt).toISOString(), outcome: 'sent', transport, detail: `accepted by ${transport}` }],
      telemetry_note: DELIVERY_TELEMETRY_NOTE,
    };

    // Per-version delivery counter â€” 1 for the first send of this quote issue,
    // then 2, 3... on resends so the audit reads 'sent 3 times' not just 'resent'.
    const prior = await Delivery.filter({ quote_issue_key: estimateQuoteIssueKey(estimateId, quoteVersion) }).catch(() => []);
    normalized.delivery_n = (Array.isArray(prior) ? prior.filter((r: any) => r?.deleted !== true).length : 0) + 1;

    const respondWithDelivery = async (payload: Record<string, unknown>) => {
      try {
        await ensureQuoteRecipientContact({
          customerContact: CustomerContact,
          estimate,
          delivery: normalized,
          createWithRecovery: createFoundationRecordWithRecovery,
        });
      } catch (error: any) {
        // Delivery is already verified; a contact-sync failure must not make a sent quote appear unsent.
        console.error("Quote recipient CustomerContact sync failed:", error?.message || error);
        payload.contact_warning = "Quote delivery is recorded, but the recipient could not be added to Customer Contacts.";
      }
      // last_contacted_at tracks real customer contact (quote sent) for reporting.
      const customerId = cleanText(estimate?.customer_id);
      if (customerId) {
        await base44.asServiceRole.entities.Customer.updateMany(
          { id: customerId },
          { last_contacted_at: new Date().toISOString() }
        ).catch((e: any) => {
          payload.contact_warning = [payload.contact_warning, `last_contacted_at update failed: ${String(e?.message || e)}`].filter(Boolean).join(" ");
          return null;
        });
      }
      return Response.json(payload);
    };

    let rows = await Delivery.filter({ idempotency_key: idempotencyKey });
    if (!Array.isArray(rows)) throw new Error('Quote delivery audit lookup did not return a delivery list.');
    if (!rows.length) {
      rows = await Delivery.filter({ gmail_message_id: gmailMessageId });
      if (!Array.isArray(rows)) throw new Error('Quote delivery Gmail-id lookup did not return a delivery list.');
    }
    if (rows.length) {
      if (rows.some((row: any) => !sameDelivery(row, normalized))) {
        return Response.json({ error: 'A delivery audit with this Gmail message id conflicts with the supplied Estimate/version/PDF fingerprint.' }, { status: 409 });
      }
      if (rows.length > 1) {
        return Response.json({ error: 'Multiple delivery audit rows already exist for this Gmail message id. No history was changed automatically.' }, { status: 409 });
      }
      return await respondWithDelivery({ delivery: rows[0], reused: true });
    }

    // Internal approval gate: a quote above the configured threshold cannot be
    // recorded as sent until a manager approves it â€” either live (the session
    // user carries can_approve_quotes) or through a recorded internal_approval.
    // The pre-send authorize_send action runs the same check before Gmail is
    // invoked, so this write is the enforcement backstop.
    await assertQuoteSendAuthorized({
      Settings,
      estimate,
      quoteTotal: Math.max(normalized.quote_total, money(estimate.quote_total)),
      user,
    });

    let created: any = null;
    let createError: any = null;
    try {
      created = await Delivery.create(normalized);
    } catch (error) {
      createError = error;
    }

    await new Promise((resolve) => setTimeout(resolve, 50));
    const afterCreate = await Delivery.filter({ idempotency_key: idempotencyKey });
    if (!Array.isArray(afterCreate)) throw new Error('Quote delivery create outcome could not be verified safely.');

    if (!created?.id) {
      if (afterCreate.length === 1 && sameDelivery(afterCreate[0], normalized)) {
        return await respondWithDelivery({ delivery: afterCreate[0], reused: true, recovered_after_create_error: true });
      }
      if (afterCreate.length > 0) {
        throw new Error('Quote delivery creation became ambiguous. No uncertain delivery row was deleted.');
      }
      throw createError || new Error('Quote delivery audit could not be created or verified.');
    }

    const canonical = canonicalDelivery(afterCreate) || created;
    if (!sameDelivery(canonical, normalized)) {
      throw new Error('Quote delivery verification resolved a conflicting audit row.');
    }

    if (afterCreate.length > 1 && canonical?.id === created.id) {
      throw new Error('A concurrent quote delivery audit was detected. The earlier canonical history was preserved and no uncertain row was deleted.');
    }

    if (canonical?.id && created?.id && canonical.id !== created.id) {
      const createdVersion = String(created.updated_date || '').trim();
      if (!createdVersion) {
        throw new Error('A duplicate quote delivery audit was detected, but the losing row has no version metadata.');
      }
      const deleted = await Delivery.deleteMany({
        id: created.id,
        estimate_id: estimateId,
        idempotency_key: idempotencyKey,
        updated_date: createdVersion,
      });
      if (!deleted || deleted.deleted !== 1) {
        throw new Error('A duplicate quote delivery audit changed before cleanup. No uncertain row was deleted.');
      }
      return await respondWithDelivery({ delivery: canonical, reused: true, concurrent_duplicate_discarded: true });
    }

    return await respondWithDelivery({ delivery: canonical, reused: false });
  } catch (error) {
    const status = Number(error?.status || 500);
    const safeStatus = [400, 401, 403, 404, 409, 429, 503].includes(status) ? status : 500;
    console.error('recordEstimateQuoteDelivery error:', error?.message || error);
    return Response.json({
      error: safeStatus === 500 ? 'Quote delivery audit could not be recorded safely.' : error?.message,
    }, { status: safeStatus });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';

const ESTIMATE_REFERENCE_ENTITIES = [
  'BuilderPriceRevision',
  'BuilderProduct',
  'EstimateAcceptance',
  'EstimateQuoteDelivery',
  'EstimateRevision',
  'WorkOrder',
];

const clean = (value: unknown) => String(value || '').trim();

const canonicalRow = (rows: any[] = []) => rows.slice().sort((a, b) => {
  const aTime = Date.parse(a?.created_date || a?.updated_date || '') || 0;
  const bTime = Date.parse(b?.created_date || b?.updated_date || '') || 0;
  if (aTime !== bTime) return aTime - bTime;
  return String(a?.id || '').localeCompare(String(b?.id || ''));
})[0] || null;

const stripCreationProtectedFields = (input: any = {}) => {
  const {
    id: _id,
    created_date: _createdDate,
    updated_date: _updatedDate,
    created_by: _createdBy,
    created_by_id: _createdById,
    creation_request_key: _creationRequestKey,
    work_order_id: _workOrderId,
    line_items: _lineItems,
    total_cost: _totalCost,
    quote_total: _quoteTotal,
    quote_issue_date: _quoteIssueDate,
    quote_version: _quoteVersion,
    cancel_reason: _cancelReason,
    edit_reason: _editReason,
    pipeline_sync_pending: _pipelineSyncPending,
    pipeline_sync_error: _pipelineSyncError,
    last_product_removal_key: _lastProductRemovalKey,
    last_product_removal_line_id: _lastProductRemovalLineId,
    last_product_removal_at: _lastProductRemovalAt,
    ...rest
  } = input || {};
  return rest;
};

const sameCreateIdentity = (row: any = {}, target: any = {}) => (
  clean(row.project_name) === clean(target.project_name) &&
  clean(row.client_name) === clean(target.client_name) &&
  clean(row.customer_id) === clean(target.customer_id) &&
  clean(row.estimate_number) === clean(target.estimate_number)
);

async function estimateReference(base44: any, estimateId: string) {
  for (const entityName of ESTIMATE_REFERENCE_ENTITIES) {
    const entity = base44.asServiceRole.entities[entityName];
    if (!entity?.filter) continue;
    const rows = await entity.filter({ estimate_id: estimateId });
    if ((rows || []).length) return entityName;
  }
  return '';
}

async function canDiscardRaceDuplicate(base44: any, row: any) {
  if (!row?.id) return { ok: false, reason: 'missing Estimate id', record: null };
  const EstimateService = base44.asServiceRole.entities.AllInOneEstimate;
  let live;
  try {
    live = await EstimateService.get(row.id);
  } catch {
    return { ok: false, reason: 'the losing Draft could not be re-read safely', record: null };
  }
  if (!live?.id) return { ok: true, reason: '', record: null };
  if (clean(live.status || 'draft') !== 'draft') return { ok: false, reason: `status is ${live.status}`, record: live };
  if (clean(live.work_order_id)) return { ok: false, reason: 'work_order_id is already set', record: live };
  if ((live.line_items || []).length) return { ok: false, reason: 'Products are already attached', record: live };
  const referencedBy = await estimateReference(base44, live.id);
  if (referencedBy) return { ok: false, reason: `${referencedBy} already references it`, record: live };
  return { ok: true, reason: '', record: live };
}

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const body = await req.json().catch(() => ({}));
    await authenticateSignShopSession(base44, body?.session_token);
    const creationKey = clean(body?.creation_key);
    const estimateInput = body?.estimate && typeof body.estimate === 'object' ? body.estimate : {};
    // New Estimate creation establishes only a clean Draft shell. Relationships,
    // Products, totals, issued-quote identity, lifecycle recovery markers, and
    // removal receipts are created later by their dedicated guarded workflows.
    const estimate = stripCreationProtectedFields(estimateInput);
    estimate.project_name = clean(estimate.project_name);
    estimate.client_name = clean(estimate.client_name);
    estimate.customer_id = clean(estimate.customer_id) || null;
    estimate.estimate_number = clean(estimate.estimate_number);
    estimate.status = clean(estimate.status || 'draft') || 'draft';

    if (!creationKey || creationKey.length > 256) {
      return Response.json({ error: 'A valid Estimate creation key is required.' }, { status: 400 });
    }
    if (!estimate.project_name) {
      return Response.json({ error: 'Estimate description is required.' }, { status: 400 });
    }
    if (estimate.status !== 'draft') {
      return Response.json({ error: 'New Estimate creation can only create Draft estimates.' }, { status: 400 });
    }

    const EstimateUser = base44.entities.AllInOneEstimate;
    const EstimateService = base44.asServiceRole.entities.AllInOneEstimate;

    // estimate_number uniqueness: a supplied number must not collide with a
    // live estimate unless the caller explicitly opts in (same-number clone).
    if (estimate.estimate_number && body?.allow_estimate_number_reuse !== true) {
      const clashes = await EstimateService.filter({ estimate_number: estimate.estimate_number }).catch(() => []);
      const live = (Array.isArray(clashes) ? clashes : []).filter(
        (row: any) => row?.deleted !== true && clean(row?.estimate_number) === estimate.estimate_number
      );
      if (live.length) {
        return Response.json({ error: `Estimate number ${estimate.estimate_number} is already used by another estimate.` }, { status: 409 });
      }
    }

    const readKeyedRows = async () => {
      const rows = await EstimateService.filter({ creation_request_key: creationKey });
      if (!Array.isArray(rows)) {
        throw Object.assign(new Error('Estimate creation receipt lookup did not return a verifiable record list.'), { statusCode: 409 });
      }
      return rows;
    };
    const validateKeyedRows = (rows: any[] = [], { allowMultiple = false } = {}) => {
      const mismatches = rows.filter((row: any) => !sameCreateIdentity(row, estimate));
      if (mismatches.length) {
        throw Object.assign(new Error('This Estimate creation receipt is already associated with different client/project/estimate-number data. No Estimate was changed.'), { statusCode: 409 });
      }
      if (!allowMultiple && rows.length > 1) {
        throw Object.assign(new Error('Multiple Estimates already share this creation receipt. No uncertain Estimate was deleted; review the duplicate Drafts before retrying.'), { statusCode: 409 });
      }
      return canonicalRow(rows);
    };

    let existingRows = await readKeyedRows();
    const existing = validateKeyedRows(existingRows);
    if (existing?.id) return Response.json({ estimate: existing, reused: true });

    let created;
    try {
      created = await EstimateService.create({
        ...estimate,
        creation_request_key: creationKey,
      });
    } catch (createError) {
      // A datastore response can be lost after persistence. Re-read by the
      // creation receipt before surfacing the error so the caller can still
      // receive the already-created Estimate on the same attempt when possible.
      try {
        existingRows = await readKeyedRows();
      } catch (verificationError) {
        throw Object.assign(new Error(
          `Estimate create response was unavailable and its recovery lookup also failed. Do not retry blindly; reload Estimates first. ${verificationError?.message || ''}`.trim()
        ), { statusCode: 409 });
      }
      const recovered = validateKeyedRows(existingRows);
      if (recovered?.id) return Response.json({ estimate: recovered, reused: true, recovered_after_create_error: true });
      throw createError;
    }

    await new Promise((resolve) => setTimeout(resolve, 50));
    let afterCreateRows;
    try {
      afterCreateRows = await readKeyedRows();
    } catch (verificationError) {
      throw Object.assign(new Error(
        `Estimate was created, but its concurrent verification read failed. Do not retry blindly; reload Estimates first. ${verificationError?.message || ''}`.trim()
      ), { statusCode: 409 });
    }
    const canonical = validateKeyedRows(afterCreateRows, { allowMultiple: true }) || created;

    if (afterCreateRows.length > 1 && canonical?.id === created?.id) {
      return Response.json({
        error: 'A concurrent Estimate was created with the same creation receipt after this request became canonical. The canonical Draft was preserved and no uncertain concurrent row was deleted; review the duplicate Drafts before continuing.',
      }, { status: 409 });
    }

    if (canonical?.id && created?.id && canonical.id !== created.id) {
      const discard = await canDiscardRaceDuplicate(base44, created);
      if (!discard.ok) {
        return Response.json({
          error: `A simultaneous duplicate Estimate was detected, but the losing Draft could not be safely removed because ${discard.reason}. No Estimate was deleted.`,
        }, { status: 409 });
      }
      const losing = discard.record;
      if (!losing?.id) {
        return Response.json({ estimate: canonical, reused: true, concurrent_duplicate_discarded: true, duplicate_already_absent: true });
      }
      const losingVersion = String(losing.updated_date || '').trim();
      if (!losingVersion) {
        return Response.json({ error: 'A simultaneous duplicate Estimate was detected, but the losing Draft has no version metadata. No uncertain Estimate was deleted.' }, { status: 409 });
      }
      let deleted;
      try {
        deleted = await EstimateService.deleteMany({
          id: losing.id,
          creation_request_key: creationKey,
          updated_date: losingVersion,
        });
      } catch (deleteError) {
        let verifyFailed = false;
        const afterError = await EstimateService.filter({ id: losing.id }).catch(() => {
          verifyFailed = true;
          return null;
        });
        if (!verifyFailed && Array.isArray(afterError) && afterError.length === 0) {
          return Response.json({ estimate: canonical, reused: true, concurrent_duplicate_discarded: true, recovered_after_delete_error: true });
        }
        throw deleteError;
      }
      if (!deleted || deleted.deleted !== 1) {
        let verifyFailed = false;
        const afterDelete = await EstimateService.filter({ id: losing.id }).catch(() => {
          verifyFailed = true;
          return null;
        });
        if (!verifyFailed && Array.isArray(afterDelete) && afterDelete.length === 0) {
          return Response.json({ estimate: canonical, reused: true, concurrent_duplicate_discarded: true });
        }
        return Response.json({ error: 'The losing duplicate Estimate changed before cleanup. No uncertain Estimate was deleted; reload before retrying.' }, { status: 409 });
      }
      return Response.json({ estimate: canonical, reused: true, concurrent_duplicate_discarded: true });
    }

    return Response.json({ estimate: canonical, reused: false });
  } catch (error) {
    const status = Number(error?.status || error?.statusCode || 500);
    const safeStatus = [400, 401, 403, 404, 409, 429, 503].includes(status) ? status : 500;
    console.error('ensureNewEstimate error:', error?.message || error);
    return Response.json({
      error: safeStatus === 500 ? 'Estimate could not be created safely.' : error.message,
    }, { status: safeStatus });
  }
});

