const CUSTOMER_FIELDS = new Set([
  'company_phone',
  'contact_office_phone',
  'contact_first_name',
  'contact_last_name',
  'contact_email',
  'contact_office_ext',
  'salesperson',
  'location',
  'default_tax_group',
  'terms',
  'location_address_1',
  'billing_address_1',
  'notes',
  'legacy_client_names',
]);

const CUSTOMER_PAGE_SIZE = 500;
const CUSTOMER_VERIFY_LIMIT = 50000;

const CUSTOMER_REFERENCE_ENTITIES = [
  'VinylProject',
  'Order',
  'ChannelLetterInstallation',
  'WorkOrder',
  'MaintenanceProject',
  'Project',
  'CNCProject',
  'MetalProject',
  'FoundationProject',
  'AllInOneEstimate',
  'LaserProject',
  'CustomerNote',
  'BrickStoneProject',
  'CustomerSummary',
];

const norm = (value: unknown) => String(value || '').trim().toLowerCase();

const normalize = (value: any): any => {
  if (Array.isArray(value)) return value.map(normalize);
  if (value && typeof value === 'object') {
    return Object.keys(value).sort().reduce((result: any, key) => {
      if (value[key] !== undefined) result[key] = normalize(value[key]);
      return result;
    }, {});
  }
  return value;
};

const sameValue = (a: unknown, b: unknown) => {
  if (a !== null && a !== undefined && a !== '' && b !== null && b !== undefined && b !== '') {
    if (Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
      return Math.abs(Number(a) - Number(b)) <= 0.000001;
    }
  }
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
};

async function updateCustomerFieldsIfUnchanged(CustomerUser: any, loaded: any, fields: Record<string, unknown>, label: string) {
  const fieldNames = Object.keys(fields || {});
  if (!loaded?.id || !fieldNames.length) return loaded;

  for (let attempt = 0; attempt < 3; attempt += 1) {
    const current = await CustomerUser.get(loaded.id).catch(() => null);
    if (!current?.id) {
      throw Object.assign(new Error(`${label} could not verify the Customer before saving.`), { statusCode: 409 });
    }

    if (fieldNames.every((field) => sameValue(current[field], fields[field]))) return current;

    for (const field of fieldNames) {
      if (!sameValue(current[field], loaded[field]) && !sameValue(current[field], fields[field])) {
        throw Object.assign(new Error(`${label} changed in another session (${field}). Reload before saving. No Customer fields were overwritten.`), { statusCode: 409 });
      }
    }

    const version = String(current.updated_date || '').trim();
    if (!version) {
      throw Object.assign(new Error(`${label} is missing Customer version metadata. Reload before saving.`), { statusCode: 409 });
    }

    let result;
    try {
      result = await CustomerService.updateMany(
        { id: loaded.id, updated_date: version },
        { $set: fields },
      );
    } catch (error) {
      const afterError = await CustomerUser.get(loaded.id).catch(() => null);
      if (afterError && fieldNames.every((field) => sameValue(afterError[field], fields[field]))) return afterError;
      throw error;
    }

    if (!result || typeof result.updated !== 'number') {
      throw new Error(`${label} conditional update result could not be verified.`);
    }
    if (result.updated === 1) {
      const saved = await CustomerUser.get(loaded.id).catch(() => null);
      if (!saved?.id) throw new Error(`${label} was saved but could not be re-read.`);
      return saved;
    }
  }

  throw Object.assign(new Error(`${label} changed repeatedly while saving. Reload and try again.`), { statusCode: 409 });
}

const canonicalRow = (rows: any[] = []) => rows.slice().sort((a, b) => {
  const aTime = Date.parse(a?.created_date || a?.updated_date || '') || 0;
  const bTime = Date.parse(b?.created_date || b?.updated_date || '') || 0;
  if (aTime !== bTime) return aTime - bTime;
  return String(a?.id || '').localeCompare(String(b?.id || ''));
})[0] || null;

const cleanFields = (input: any = {}) => Object.fromEntries(
  Object.entries(input || {}).filter(([key]) => CUSTOMER_FIELDS.has(key))
);

const matchesCustomerName = (row: any, normalizedName: string) => {
  if (norm(row?.company_name) === normalizedName) return true;
  return (row?.legacy_client_names || []).some((value: unknown) => norm(value) === normalizedName);
};

async function findHistoricalMatch(CustomerService: any, normalizedName: string) {
  // Legacy aliases live inside each Customer record, so an exact company-name
  // filter alone is insufficient. Page through the full catalog with the same
  // Base44 list(sort, limit, skip) contract already used by other backends.
  // New rows sort to the end by created_date, which also keeps this scan stable
  // if another Customer is added while verification is in progress.
  const matches: any[] = [];
  let skip = 0;
  while (skip < CUSTOMER_VERIFY_LIMIT) {
    const page = await CustomerService.list('created_date', CUSTOMER_PAGE_SIZE, skip);
    if (!Array.isArray(page)) {
      throw new Error('The Customer catalog could not be verified safely. No Customer was created.');
    }
    for (const row of page) {
      if (matchesCustomerName(row, normalizedName)) matches.push(row);
    }
    if (page.length < CUSTOMER_PAGE_SIZE) return canonicalRow(matches);
    skip += CUSTOMER_PAGE_SIZE;
  }
  throw new Error(`The Customer catalog exceeds the ${CUSTOMER_VERIFY_LIMIT.toLocaleString()}-record verification safety limit. No Customer was created.`);
}

async function hasAnyCustomerReference(base44: any, customerId: string) {
  for (const entityName of CUSTOMER_REFERENCE_ENTITIES) {
    const entity = base44.asServiceRole.entities[entityName];
    if (!entity?.filter) continue;
    const rows = await entity.filter({ customer_id: customerId });
    if ((rows || []).length) return entityName;
  }
  return '';
}

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const body = await req.json().catch(() => ({}));
    await authenticateSignShopSession(base44, body?.session_token);
    const companyName = String(body?.company_name || '').trim();
    const normalizedName = norm(companyName);
    if (!companyName || !normalizedName) {
      return Response.json({ error: 'Customer company name is required.' }, { status: 400 });
    }

    const fields = cleanFields(body?.fields || {});
    const updateExisting = body?.update_existing !== false;
    const creationKey = `estimate_customer:${normalizedName}`;
    const CustomerUser = base44.entities.Customer;
    const CustomerService = base44.asServiceRole.entities.Customer;

    // Never retrofit creation receipts onto historical rows. If the live catalog
    // already contains this company/legacy name, preserve that record and simply
    // apply the same estimator fields the old client path would have written.
    const historical = await findHistoricalMatch(CustomerService, normalizedName);
    if (historical?.id) {
      const customer = updateExisting && Object.keys(fields).length
        ? await updateCustomerFieldsIfUnchanged(CustomerUser, historical, fields, 'Historical Customer synchronization')
        : historical;
      return Response.json({ customer, reused: true, historical_match: true });
    }

    // A retry after a lost create response can find the estimator-created row by
    // receipt before attempting another create.
    const readKeyedRows = async () => {
      const rows = await CustomerService.filter({ estimator_creation_key: creationKey });
      if (!Array.isArray(rows)) {
        throw Object.assign(new Error('Estimator Customer creation receipt lookup did not return a verifiable record list.'), { statusCode: 409 });
      }
      return rows;
    };
    const validateKeyedRows = (rows: any[] = [], { allowMultiple = false } = {}) => {
      const mismatches = rows.filter((row: any) => norm(row?.company_name) !== normalizedName);
      if (mismatches.length) {
        throw Object.assign(new Error('A Customer creation receipt is already associated with a different company name. No Customer was changed.'), { statusCode: 409 });
      }
      if (!allowMultiple && rows.length > 1) {
        throw Object.assign(new Error('Multiple Customers already share this estimator creation receipt. No uncertain Customer was deleted; review the duplicate Customers before retrying.'), { statusCode: 409 });
      }
      return canonicalRow(rows);
    };

    let keyedRows = await readKeyedRows();
    const keyedExisting = validateKeyedRows(keyedRows);
    if (keyedExisting?.id) {
      const customer = updateExisting && Object.keys(fields).length
        ? await updateCustomerFieldsIfUnchanged(CustomerUser, keyedExisting, fields, 'Estimator Customer synchronization')
        : keyedExisting;
      return Response.json({ customer, reused: true });
    }

    const createPayload = {
      company_name: companyName,
      customer_status: 'prospect',
      estimator_creation_key: creationKey,
      ...fields,
    };
    let created: any = null;
    let createError: any = null;
    try {
      created = await CustomerService.create(createPayload);
    } catch (error) {
      createError = error;
    }

    await new Promise((resolve) => setTimeout(resolve, 50));
    try {
      keyedRows = await readKeyedRows();
    } catch (verificationError) {
      if (!created?.id) {
        throw Object.assign(new Error(
          `Estimator Customer create response was unavailable and its recovery lookup also failed. Do not retry blindly; reload Customers first. ${verificationError?.message || ''}`.trim()
        ), { statusCode: 409 });
      }
      throw Object.assign(new Error(
        `Estimator Customer was created, but its concurrent verification read failed. Do not retry blindly; reload Customers first. ${verificationError?.message || ''}`.trim()
      ), { statusCode: 409 });
    }

    if (!created?.id) {
      const recovered = validateKeyedRows(keyedRows);
      if (recovered?.id) {
        return Response.json({ customer: recovered, reused: true, recovered_after_create_error: true });
      }
      throw createError || new Error('Estimator Customer could not be created or verified.');
    }

    const canonical = validateKeyedRows(keyedRows, { allowMultiple: true }) || created;

    if (keyedRows.length > 1 && canonical?.id === created.id) {
      return Response.json({ error: 'A concurrent Customer was created with the same estimator creation receipt after this request became canonical. The canonical Customer was preserved and no uncertain concurrent row was deleted; review the duplicate Customers before continuing.' }, { status: 409 });
    }

    if (canonical?.id && created?.id && canonical.id !== created.id) {
      // Delete only the row created by this request, only when it is still an
      // unreferenced and unchanged race duplicate. Never merge/delete historical Customers.
      const losingRows = await CustomerService.filter({ id: created.id });
      if (!Array.isArray(losingRows) || losingRows.length > 1) {
        return Response.json({ error: 'The losing duplicate Customer could not be re-read safely. No uncertain Customer was deleted.' }, { status: 409 });
      }
      const losing = losingRows[0] || null;
      if (losing?.id) {
        const referencedBy = await hasAnyCustomerReference(base44, losing.id);
        if (referencedBy) {
          return Response.json({ error: `A simultaneous Customer duplicate was detected, but the losing row is already referenced by ${referencedBy}. No Customer was deleted.` }, { status: 409 });
        }
        const losingVersion = String(losing.updated_date || '').trim();
        if (!losingVersion) {
          return Response.json({ error: 'The losing duplicate Customer has no version metadata. No uncertain Customer was deleted.' }, { status: 409 });
        }
        let deleted;
        try {
          deleted = await CustomerService.deleteMany({
            id: losing.id,
            estimator_creation_key: creationKey,
            updated_date: losingVersion,
          });
        } catch (deleteError) {
          const afterError = await CustomerService.filter({ id: losing.id }).catch(() => null);
          if (!Array.isArray(afterError) || afterError.length !== 0) throw deleteError;
          deleted = { deleted: 1 };
        }
        if (!deleted || deleted.deleted !== 1) {
          const afterDelete = await CustomerService.filter({ id: losing.id }).catch(() => null);
          if (!Array.isArray(afterDelete) || afterDelete.length !== 0) {
            return Response.json({ error: 'The losing duplicate Customer changed before cleanup. No uncertain Customer was deleted; reload before retrying.' }, { status: 409 });
          }
        }
      }
      const customer = updateExisting && Object.keys(fields).length
        ? await updateCustomerFieldsIfUnchanged(CustomerUser, canonical, fields, 'Canonical Customer synchronization')
        : canonical;
      return Response.json({
        customer,
        reused: true,
        concurrent_duplicate_discarded: true,
      });
    }

    return Response.json({ customer: canonical, reused: false });
  } catch (error) {
    const status = Number(error?.status || error?.statusCode || 500);
    const safeStatus = [400, 401, 403, 404, 409, 429, 503].includes(status) ? status : 500;
    console.error('ensureEstimateCustomer error:', error?.message || error);
    return Response.json({
      error: safeStatus === 500 ? 'Customer could not be created safely.' : error.message,
    }, { status: safeStatus });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { estimateAuditSnapshot, estimateQuoteIssueKey } from '../../shared/estimateRevisionAudit.ts';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';

const num = (value: unknown, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const REVISION_PAGE_SIZE = 500;
const REVISION_VERIFY_LIMIT = 50000;

async function loadRevisionRows(RevisionService: any, query: Record<string, unknown>) {
  const rows: any[] = [];
  let skip = 0;
  while (skip < REVISION_VERIFY_LIMIT) {
    const page = await RevisionService.filter(query, 'revision_number', REVISION_PAGE_SIZE, skip);
    if (!Array.isArray(page)) {
      throw new Error('Estimate revision history could not be verified completely.');
    }
    rows.push(...page);
    if (page.length < REVISION_PAGE_SIZE) return rows;
    skip += REVISION_PAGE_SIZE;
  }
  throw new Error(`Estimate revision history exceeds the ${REVISION_VERIFY_LIMIT.toLocaleString()}-record verification safety limit.`);
}

const canonicalOpenRevision = (rows: any[] = []) => rows
  .filter((row) => row?.revision_status === 'open')
  .slice()
  .sort((a, b) => {
    const aNum = num(a?.revision_number, Number.MAX_SAFE_INTEGER);
    const bNum = num(b?.revision_number, Number.MAX_SAFE_INTEGER);
    if (aNum !== bNum) return aNum - bNum;
    const aTime = Date.parse(a?.created_date || a?.started_at || '') || 0;
    const bTime = Date.parse(b?.created_date || b?.started_at || '') || 0;
    if (aTime !== bTime) return aTime - bTime;
    return String(a?.id || '').localeCompare(String(b?.id || ''));
  })[0] || null;

const revisionOrder = (a: any, b: any) => {
  const aTime = Date.parse(a?.created_date || a?.started_at || '') || 0;
  const bTime = Date.parse(b?.created_date || b?.started_at || '') || 0;
  if (aTime !== bTime) return aTime - bTime;
  return String(a?.id || '').localeCompare(String(b?.id || ''));
};

async function settleCreatedRevisionNumber(RevisionService: any, estimateId: string, created: any) {
  let current = created;
  for (let attempt = 0; attempt < 5; attempt += 1) {
    await new Promise((resolve) => setTimeout(resolve, 50));
    const rows = await loadRevisionRows(RevisionService, { estimate_id: estimateId });
    const live = rows.find((row) => String(row?.id || '') === String(current?.id || ''));
    if (!live) throw new Error('The newly created open Estimate revision disappeared before its sequence number could be verified.');
    current = { ...current, ...live };

    const currentNumber = num(current.revision_number);
    const collisions = rows.filter((row) => row?.id !== current.id && num(row?.revision_number) === currentNumber);
    if (!collisions.length) return current;

    const winner = [current, ...collisions].slice().sort(revisionOrder)[0];
    if (winner?.id === current.id) {
      if (attempt < 4) continue;
      throw new Error('A later concurrent Estimate revision still shares this revision number. The earlier canonical row was not renumbered; reload the revision history before retrying.');
    }

    const nextNumber = Math.max(0, ...rows.map((row) => num(row?.revision_number))) + 1;
    const version = String(current?.updated_date || '').trim();
    if (!version) throw new Error('Open Estimate revision version metadata is incomplete; concurrent-safe renumbering was blocked.');

    let result;
    try {
      result = await RevisionService.updateMany(
        { id: current.id, estimate_id: estimateId, revision_status: 'open', updated_date: version },
        { $set: { revision_number: nextNumber } },
      );
    } catch (error) {
      const afterError = await RevisionService.get(current.id).catch(() => null);
      if (afterError?.id && num(afterError.revision_number) === nextNumber) {
        current = afterError;
        continue;
      }
      throw error;
    }

    if (!result || typeof result.updated !== 'number') {
      throw new Error('Open Estimate revision conditional renumber result could not be verified.');
    }
    if (result.updated !== 1) continue;
    const updated = await RevisionService.get(current.id).catch(() => null);
    if (!updated?.id) throw new Error('Open Estimate revision was renumbered but could not be re-read.');
    current = updated;
  }

  const finalRows = await loadRevisionRows(RevisionService, { estimate_id: estimateId });
  const finalCurrent = finalRows.find((row) => String(row?.id || '') === String(current?.id || '')) || current;
  const collision = finalRows.some((row) => row?.id !== finalCurrent.id && num(row?.revision_number) === num(finalCurrent.revision_number));
  if (collision) throw new Error('Concurrent Estimate revisions could not settle on unique revision numbers. No duplicate number was accepted silently.');
  return finalCurrent;
}

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const body = await req.json().catch(() => ({}));
    // Revision writes were gated solely on the custom session token, which left
    // the audit trail empty when callers ran under plain request-context auth.
    // Fall back to auth.me() so either auth path unblocks the write.
    let actor = null;
    try { actor = await authenticateSignShopSession(base44, body?.session_token); }
    catch { actor = await base44.auth.me().catch(() => null); }
    if (!actor?.id && !actor?.email) return Response.json({ error: 'Authentication required.' }, { status: 401 });
    const estimateId = String(body?.estimate_id || '').trim();
    const expectedUpdatedDate = String(body?.expected_estimate_updated_date || '').trim();
    const reason = String(body?.reason || '').trim();

    if (!estimateId || !reason) {
      return Response.json({ error: 'Estimate and revision reason are required.' }, { status: 400 });
    }

    const EstimateUser = base44.entities.AllInOneEstimate;
    const RevisionService = base44.asServiceRole.entities.EstimateRevision;

    const estimate = await EstimateUser.get(estimateId).catch(() => null);
    if (!estimate?.id) return Response.json({ error: 'Estimate could not be verified before starting a revision.' }, { status: 404 });
    if (expectedUpdatedDate && estimate.updated_date && expectedUpdatedDate !== estimate.updated_date) {
      return Response.json({ error: 'This estimate changed in another session. Reload before starting a revision.' }, { status: 409 });
    }
    if (estimate.pipeline_sync_pending) {
      return Response.json({ error: 'Sales Pipeline synchronization is still pending. Retry that synchronization before starting another estimate revision.' }, { status: 409 });
    }
    const pendingLine = (estimate.line_items || []).find((line: any) => {
      const pending = line?.price_acceptance_pending;
      return pending && typeof pending === 'object' && String(pending.key || '').trim();
    });
    if (pendingLine) {
      return Response.json({ error: 'A Builder mutation recovery is still pending. Resume that Product operation before starting an Estimate Revision.' }, { status: 409 });
    }

    // One Estimate may have at most one active manual revision. Returning the
    // canonical existing row makes retries naturally idempotent even when the
    // browser lost the create response.
    let openRows = await loadRevisionRows(RevisionService, { estimate_id: estimateId, revision_status: 'open' });
    const existing = canonicalOpenRevision(openRows || []);
    if (existing) return Response.json({ revision: existing, reused: true });

    const allRows = await loadRevisionRows(RevisionService, { estimate_id: estimateId });
    const revisionNumber = Math.max(0, ...(allRows || []).map((row) => num(row?.revision_number))) + 1;
    const timestamp = new Date().toISOString();
    const idempotencyKey = `open_revision:${estimateId}:${expectedUpdatedDate || estimate.updated_date || revisionNumber}`;
    const before = estimateAuditSnapshot(estimate);
    const quoteVersion = Math.max(0, Math.floor(num(before.quote_version)));

    // Build the immutable pre-revision state from the persisted Estimate instead
    // of trusting a browser-supplied audit snapshot. The browser still supplies
    // the human reason; pricing/status/scope evidence comes from server state.
    const created = await RevisionService.create({
      estimate_id: estimateId,
      revision_number: revisionNumber,
      quote_version: quoteVersion,
      quote_issue_key: estimateQuoteIssueKey(estimateId, quoteVersion),
      revision_type: 'manual_revision',
      revision_status: 'open',
      reason,
      previous_status: before.status || 'draft',
      new_status: before.status || 'draft',
      previous_quote_total: num(before.quote_total),
      new_quote_total: num(before.quote_total),
      previous_total_cost: num(before.total_cost),
      new_total_cost: num(before.total_cost),
      change_summary: ['Revision opened — changes not yet finalized'],
      estimate_snapshot_before: before,
      estimate_snapshot_after: {},
      work_order_id: estimate.work_order_id || '',
      delivery_evidence: {},
      idempotency_key: idempotencyKey,
      started_at: timestamp,
      completed_at: '',
    });

    // Base44 has no unique constraint for "one open revision per Estimate".
    // Re-read after create so simultaneous staff sessions converge on the
    // earliest canonical open row. Each losing request deletes only the row it
    // created; unrelated lifecycle history is never modified.
    await new Promise((resolve) => setTimeout(resolve, 50));
    openRows = await loadRevisionRows(RevisionService, { estimate_id: estimateId, revision_status: 'open' });
    const canonical = canonicalOpenRevision(openRows || []) || created;

    if (canonical?.id && created?.id && canonical.id !== created.id) {
      const createdVersion = String(created.updated_date || '').trim();
      if (!createdVersion) {
        throw new Error('A duplicate open Estimate revision was detected, but the losing row has no version metadata. No uncertain revision was deleted.');
      }
      const deleted = await RevisionService.deleteMany({
        id: created.id,
        estimate_id: estimateId,
        idempotency_key: idempotencyKey,
        revision_status: 'open',
        updated_date: createdVersion,
      });
      if (!deleted || deleted.deleted !== 1) {
        throw new Error('A duplicate open Estimate revision changed before cleanup. No uncertain revision was deleted; reload the Estimate revision history before retrying.');
      }
      return Response.json({ revision: canonical, reused: true, concurrent_duplicate_discarded: true });
    }

    const settled = await settleCreatedRevisionNumber(RevisionService, estimateId, canonical || created);
    return Response.json({ revision: settled, reused: false });
  } catch (error) {
    const status = Number(error?.status || error?.statusCode || 500);
    const safeStatus = [400, 401, 403, 404, 409, 429, 503].includes(status) ? status : 500;
    console.error('ensureOpenEstimateRevision error:', error?.message || error);
    return Response.json({
      error: safeStatus === 500 ? 'Estimate revision could not be started safely.' : error.message,
    }, { status: safeStatus });
  }
});

