    }
    const authoritativeWorkOrderId = String(estimate.work_order_id || '').trim();
    if (revisionType === 'conversion') {
      const requestedWorkOrderId = String(revision?.work_order_id || '').trim();
      if (!requestedWorkOrderId || authoritativeWorkOrderId !== requestedWorkOrderId) {
        return Response.json({ error: 'Conversion lifecycle history does not match the linked Work Order.' }, { status: 409 });
      }
    }

    // Derive the "before" snapshot server-side from the most recent completed
    // revision's estimate_snapshot_after, so a caller cannot rewrite history by
    // supplying a fabricated or stale before-snapshot. When no prior completed
    // revision exists, fall back to an empty object (the Estimate's current
    // server state is still captured authoritatively as the "after" snapshot).
    const allRows = await loadRevisionRows(RevisionService, { estimate_id: estimateId });
    const priorCompleted = (allRows || [])
      .filter((row) => row?.revision_status === 'completed')
      .slice()
      .sort((a, b) => num(b?.revision_number) - num(a?.revision_number))[0];
    const before = priorCompleted?.estimate_snapshot_after && typeof priorCompleted.estimate_snapshot_after === 'object'
      ? JSON.parse(JSON.stringify(priorCompleted.estimate_snapshot_after))
      : {};
    const after = estimateAuditSnapshot(estimate);
    const quoteVersion = Math.max(0, Math.floor(estimateAuditNumber(after.quote_version)));
    const revisionNumber = Math.max(0, ...(allRows || []).map((row) => num(row?.revision_number))) + 1;
    const timestamp = new Date().toISOString();

    // Persist current Estimate state from the server as the authoritative "after"
    // side of lifecycle history. Caller-supplied status/totals/snapshots cannot
    // override the saved Estimate state represented by this immutable row.
    const created = await RevisionService.create({
      estimate_id: estimateId,
      revision_number: revisionNumber,
      quote_version: quoteVersion,
      quote_issue_key: estimateQuoteIssueKey(estimateId, quoteVersion),
      revision_type: revisionType,
      revision_status: 'completed',
      reason,
      previous_status: String(before.status || 'draft'),
      new_status: String(after.status || 'draft'),
      previous_quote_total: estimateAuditNumber(before.quote_total),
      new_quote_total: estimateAuditNumber(after.quote_total),
      previous_total_cost: estimateAuditNumber(before.total_cost),
      new_total_cost: estimateAuditNumber(after.total_cost),
      change_summary: summarizeEstimateAuditChanges(before, after),
      estimate_snapshot_before: before,
      estimate_snapshot_after: after,
      work_order_id: authoritativeWorkOrderId,
      delivery_evidence: revision?.delivery_evidence && typeof revision.delivery_evidence === 'object' ? revision.delivery_evidence : {},
      idempotency_key: idempotencyKey,
      notes: idempotencyKey,
      started_at: timestamp,
      completed_at: timestamp,
    });

    // Base44 does not expose a database unique constraint for this entity. Re-read
    // after create so simultaneous staff submissions converge on the earliest
    // completed row for this exact lifecycle key. Only this request's losing row
    // is removed; unrelated history and open manual revisions are never touched.
    await new Promise((resolve) => setTimeout(resolve, 50));
    let afterCreate = await loadRevisionRows(RevisionService, {
      estimate_id: estimateId,
      idempotency_key: idempotencyKey,
    });
    if (!(afterCreate || []).length) {
      afterCreate = await loadRevisionRows(RevisionService, {
        estimate_id: estimateId,
        notes: idempotencyKey,
      });
    }
    const canonical = canonicalRevision(afterCreate || []) || created;

    if (canonical?.id && created?.id && canonical.id !== created.id) {
      const createdVersion = String(created.updated_date || '').trim();
      if (!createdVersion) {
        throw new Error('A duplicate lifecycle revision was detected, but the losing row has no version metadata. No uncertain revision was deleted.');
      }
      const deleted = await RevisionService.deleteMany({
        id: created.id,
        estimate_id: estimateId,
        idempotency_key: idempotencyKey,
        revision_status: 'completed',
        updated_date: createdVersion,
      });
      if (!deleted || deleted.deleted !== 1) {
        throw new Error('A duplicate lifecycle revision changed before cleanup. No uncertain revision was deleted; reload the Estimate revision history before retrying.');
      }
      return Response.json({ revision: canonical, reused: true, concurrent_duplicate_discarded: true });
    }

    const settled = await settleCreatedRevisionNumber(RevisionService, estimateId, canonical || created);
    return Response.json({ revision: settled, reused: false });
  } catch (error) {
    const status = Number(error?.status || error?.statusCode || 500);
    const safeStatus = [400, 401, 403, 404, 409, 429, 503].includes(status) ? status : 500;
    console.error('ensureEstimateLifecycleRevision error:', error?.message || error);
    return Response.json({
      error: safeStatus === 500 ? 'Estimate lifecycle revision could not be recorded safely.' : error.message,
    }, { status: safeStatus });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { estimateAuditNumber, estimateAuditSnapshot, estimateQuoteIssueKey, summarizeEstimateAuditChanges } from '../../shared/estimateRevisionAudit.ts';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';

const text = (value: unknown, max = 2000) => String(value || '').trim().slice(0, max);
const whole = (value: unknown, fallback = 0) => {
  const parsed = Math.floor(Number(value));
  return Number.isFinite(parsed) ? parsed : fallback;
};

function safeDeliveryEvidence(input: any = {}) {
  const sentAt = text(input?.sent_at, 80);
  const fileUrl = text(input?.attachment_file_url, 4000);
  return {
    delivery_id: text(input?.delivery_id, 128),
    gmail_message_id: text(input?.gmail_message_id, 512),
    recipient_email: text(input?.recipient_email, 320),
    sent_at: sentAt && Number.isFinite(Date.parse(sentAt)) ? new Date(sentAt).toISOString() : '',
    // Only http(s) evidence URLs are stored — javascript:/data: and other
    // schemes can never be persisted as delivery evidence.
    attachment_file_url: /^https?:\/\//i.test(fileUrl) ? fileUrl : '',
    attachment_sha256: text(input?.attachment_sha256, 128),
    attachment_size_bytes: Math.max(0, Number(input?.attachment_size_bytes || 0)),
  };
}

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const body = await req.json().catch(() => ({}));
    // Fall back to auth.me() when no sign-shop session token is supplied so
    // plain request-context auth can write audit rows too.
    let actor = null;
    try { actor = await authenticateSignShopSession(base44, body?.session_token); }
    catch { actor = await base44.auth.me().catch(() => null); }
    if (!actor?.id && !actor?.email) return Response.json({ error: 'Authentication required.' }, { status: 401 });
    const action = text(body?.action, 80);
    const estimateId = text(body?.estimate_id, 128);
    const RevisionService = base44.asServiceRole.entities.EstimateRevision;
    const EstimateUser = base44.entities.AllInOneEstimate;

    if (!estimateId) return Response.json({ error: 'Estimate id is required.' }, { status: 400 });

    if (action === 'complete_manual_revision') {
      const revisionId = text(body?.revision_id, 128);
      const expectedRevisionUpdatedDate = text(body?.expected_revision_updated_date, 100);
      const expectedEstimateUpdatedDate = text(body?.expected_estimate_updated_date, 100);
      if (!revisionId) return Response.json({ error: 'Revision id is required.' }, { status: 400 });

      const revision = await RevisionService.get(revisionId).catch(() => null);
      if (!revision?.id || String(revision.estimate_id || '') !== estimateId) {
        return Response.json({ error: 'Estimate revision could not be verified.' }, { status: 404 });
      }
      if (revision.revision_status === 'completed') {
        return Response.json({ revision, reused: true });
      }
      if (revision.revision_status !== 'open' || revision.revision_type !== 'manual_revision') {
        return Response.json({ error: 'Only an open manual Estimate revision can be completed.' }, { status: 409 });
      }
      if (expectedRevisionUpdatedDate && revision.updated_date && expectedRevisionUpdatedDate !== revision.updated_date) {
        return Response.json({ error: 'This Estimate revision changed in another session. Reload before completing it.' }, { status: 409 });
      }

      const estimate = await EstimateUser.get(estimateId).catch(() => null);
      if (!estimate?.id) return Response.json({ error: 'Estimate could not be verified before completing its revision.' }, { status: 404 });
      if (expectedEstimateUpdatedDate && String(estimate.updated_date || '') !== expectedEstimateUpdatedDate) {
        return Response.json({ error: 'This estimate changed in another session. Reload before completing its revision.' }, { status: 409 });
      }

      const before = revision.estimate_snapshot_before && typeof revision.estimate_snapshot_before === 'object'
        ? JSON.parse(JSON.stringify(revision.estimate_snapshot_before))
        : {};
      const after = estimateAuditSnapshot(estimate);
      const quoteVersion = Math.max(0, whole(after.quote_version));
      const patch = {
        revision_status: 'completed',
        quote_version: quoteVersion,
        quote_issue_key: estimateQuoteIssueKey(estimateId, quoteVersion),
        new_status: String(after.status || revision.previous_status || 'draft'),
        new_quote_total: estimateAuditNumber(after.quote_total),
        new_total_cost: estimateAuditNumber(after.total_cost),
        change_summary: summarizeEstimateAuditChanges(before, after),
        estimate_snapshot_after: after,
        completed_at: new Date().toISOString(),
        work_order_id: String(estimate.work_order_id || revision.work_order_id || ''),
      };

      const version = String(revision.updated_date || '').trim();
      if (!version) return Response.json({ error: 'Estimate revision version metadata is incomplete.' }, { status: 409 });
      const result = await RevisionService.updateMany(
        { id: revisionId, estimate_id: estimateId, revision_status: 'open', revision_type: 'manual_revision', updated_date: version },
        { $set: patch },
      );
      if (!result || typeof result.updated !== 'number') {
        throw new Error('Estimate revision completion result could not be verified.');
      }
      const current = await RevisionService.get(revisionId).catch(() => null);
      if (result.updated !== 1) {
        if (current?.revision_status === 'completed' && String(current.estimate_id || '') === estimateId) {
          return Response.json({ revision: current, reused: true });
        }
        return Response.json({ error: 'The Estimate revision changed before completion. Reload before retrying.' }, { status: 409 });
      }
      if (!current?.id || current.revision_status !== 'completed') {
        throw new Error('Estimate revision was updated but could not be verified as completed.');
      }
      return Response.json({ revision: current, reused: false });
    }

    if (action === 'attach_delivery_evidence') {
      const quoteVersion = Math.max(0, whole(body?.quote_version));
      if (quoteVersion <= 0) return Response.json({ error: 'Issued Quote Version is required.' }, { status: 400 });
      const issueKey = estimateQuoteIssueKey(estimateId, quoteVersion);
      const rows = await RevisionService.filter({ estimate_id: estimateId, quote_issue_key: issueKey });
      if (!Array.isArray(rows)) throw new Error('Quote issuance revision history could not be verified.');

      const issuanceRevision = rows.find((row: any) => {
        const beforeVersion = Math.max(0, whole(row?.estimate_snapshot_before?.quote_version));
        const afterVersion = Math.max(0, whole(row?.estimate_snapshot_after?.quote_version, row?.quote_version));
        return row?.revision_status === 'completed' && afterVersion === quoteVersion && beforeVersion !== afterVersion;
      }) || null;
      if (!issuanceRevision?.id) {
        return Response.json({ revision: null, warning: `Quote Version ${quoteVersion} was delivered, but its issuance revision could not be located for fallback delivery evidence.` });
      }

      const existing = issuanceRevision.delivery_evidence || {};
      if (existing.gmail_message_id || existing.delivery_id || existing.attachment_file_url) {
        return Response.json({ revision: issuanceRevision, reused: true });
      }

      let evidence = safeDeliveryEvidence(body?.delivery_evidence || {});
      if (evidence.delivery_id) {
        const delivery = await base44.asServiceRole.entities.EstimateQuoteDelivery.get(evidence.delivery_id).catch(() => null);
        if (!delivery?.id || String(delivery.estimate_id || '') !== estimateId || Math.max(0, whole(delivery.quote_version)) !== quoteVersion || delivery.delivery_status !== 'sent') {
          return Response.json({ error: 'The selected quote delivery does not belong to this Estimate/version.' }, { status: 409 });
        }
        evidence = safeDeliveryEvidence({
          delivery_id: delivery.id,
          gmail_message_id: delivery.gmail_message_id,
          recipient_email: delivery.recipient_email,
          sent_at: delivery.sent_at,
          attachment_file_url: delivery.attachment_file_url,
          attachment_sha256: delivery.attachment_sha256,
          attachment_size_bytes: delivery.attachment_size_bytes,
        });
      }

      if (!evidence.gmail_message_id && !evidence.delivery_id && !evidence.attachment_file_url) {
        return Response.json({ error: 'Delivery evidence is incomplete.' }, { status: 400 });
      }

      const version = String(issuanceRevision.updated_date || '').trim();
      if (!version) return Response.json({ error: 'Issuance revision version metadata is incomplete.' }, { status: 409 });
      const result = await RevisionService.updateMany(
        { id: issuanceRevision.id, estimate_id: estimateId, quote_issue_key: issueKey, revision_status: 'completed', updated_date: version },
        { $set: { delivery_evidence: evidence } },
      );
      if (!result || typeof result.updated !== 'number') throw new Error('Quote delivery evidence update result could not be verified.');
      const current = await RevisionService.get(issuanceRevision.id).catch(() => null);
      if (result.updated !== 1) {
        const currentEvidence = current?.delivery_evidence || {};
        if (currentEvidence.gmail_message_id || currentEvidence.delivery_id || currentEvidence.attachment_file_url) {
          return Response.json({ revision: current, reused: true });
        }
        return Response.json({ error: 'The quote issuance revision changed before delivery evidence was attached. Reload before retrying.' }, { status: 409 });
      }
      if (!current?.id) throw new Error('Quote delivery evidence was updated but could not be re-read.');
      return Response.json({ revision: current, reused: false });
    }

    return Response.json({ error: 'Invalid Estimate revision audit action.' }, { status: 400 });
  } catch (error) {
    const status = Number(error?.status || error?.statusCode || 500);
    const safeStatus = [400, 401, 403, 404, 409, 429, 503].includes(status) ? status : 500;
    console.error('updateEstimateRevisionAudit error:', error?.message || error);
    return Response.json({
      error: safeStatus === 500 ? 'Estimate revision audit could not be updated safely.' : error.message,
    }, { status: safeStatus });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';

const num = (value: unknown, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

const canonicalRevision = (rows: any[] = []) => rows
  .slice()
  .sort((a, b) => {
    const aTime = Date.parse(a?.created_date || '') || 0;
    const bTime = Date.parse(b?.created_date || '') || 0;
    if (aTime !== bTime) return aTime - bTime;
    return String(a?.id || '').localeCompare(String(b?.id || ''));
  })[0] || null;

const sameMoney = (a: unknown, b: unknown) => Math.abs(num(a) - num(b)) <= 0.005;
const ALLOWED_REASONS = new Set(['update_price', 'initial_freeze', 'manual_adjustment', 'reattach']);

async function settleRevisionNumber(RevisionService: any, builderProductId: string, created: any) {
  let current = created;
  for (let attempt = 0; attempt < 5; attempt += 1) {
    await new Promise((resolve) => setTimeout(resolve, 50));
    const rows = await RevisionService.filter({ builder_product_id: builderProductId });
    if (!Array.isArray(rows)) throw new Error('Builder price revision history could not be verified after creation.');
    const live = rows.find((row) => String(row?.id || '') === String(current?.id || ''));
    if (!live) throw new Error('The newly created Builder price revision disappeared before its sequence number could be verified.');
    current = { ...current, ...live };

    const revisionNumber = num(current.revision_number);
    const collisions = rows.filter((row) => row?.id !== current.id && num(row?.revision_number) === revisionNumber);
    if (!collisions.length) return current;

    const winner = [current, ...collisions].slice().sort((a, b) => {
      const aTime = Date.parse(a?.created_date || '') || 0;
      const bTime = Date.parse(b?.created_date || '') || 0;
      if (aTime !== bTime) return aTime - bTime;
      return String(a?.id || '').localeCompare(String(b?.id || ''));
    })[0];
    if (winner?.id === current.id) {
      if (attempt < 4) continue;
      throw new Error('A later concurrent Builder price revision still shares this revision number. The earlier canonical row was not renumbered; reload the pricing history before retrying.');
    }

    const nextNumber = Math.max(0, ...rows.map((row) => num(row?.revision_number))) + 1;
    const version = String(current?.updated_date || '').trim();
    if (!version) throw new Error('Builder price revision version metadata is incomplete; concurrent-safe renumbering was blocked.');

    let result;
    try {
      result = await RevisionService.updateMany(
        { id: current.id, builder_product_id: builderProductId, updated_date: version },
        { $set: { revision_number: nextNumber } },
      );
    } catch (error) {
      const afterError = await RevisionService.get(current.id).catch(() => null);
      if (afterError?.id && num(afterError.revision_number) === nextNumber) {
        current = afterError;
        continue;
      }
      throw error;
    }
    if (!result || typeof result.updated !== 'number') {
      throw new Error('Builder price revision conditional renumber result could not be verified.');
    }
    if (result.updated !== 1) continue;
    const updated = await RevisionService.get(current.id).catch(() => null);
    if (!updated?.id) throw new Error('Builder price revision was renumbered but could not be re-read.');
    current = updated;
  }

  const finalRows = await RevisionService.filter({ builder_product_id: builderProductId });
  if (!Array.isArray(finalRows)) throw new Error('Builder price revision history could not be verified after renumbering.');
  const finalCurrent = finalRows.find((row) => String(row?.id || '') === String(current?.id || '')) || current;
  const collision = finalRows.some((row) => row?.id !== finalCurrent.id && num(row?.revision_number) === num(finalCurrent.revision_number));
  if (collision) throw new Error('Concurrent Builder price revisions could not settle on unique revision numbers. No duplicate number was accepted silently.');
  return finalCurrent;
}

function assertSameOperation(existing: any, revision: any) {
  if (!existing) return;
  if (
    String(existing?.estimate_id || '') !== String(revision?.estimate_id || '') ||
    String(existing?.builder_product_id || '') !== String(revision?.builder_product_id || '') ||
    existing?.reason !== revision?.reason ||
    !sameMoney(existing?.previous_total_cost, revision?.previous_total_cost) ||
    !sameMoney(existing?.new_total_cost, revision?.new_total_cost) ||
    !sameMoney(existing?.previous_customer_price, revision?.previous_customer_price) ||
    !sameMoney(existing?.new_customer_price, revision?.new_customer_price)
  ) {
    throw new Error('The Builder price idempotency key is already associated with different pricing data.');
  }
}

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const body = await req.json().catch(() => ({}));
    // Fall back to auth.me() when no sign-shop session token is supplied so
    // request-context auth can write price-revision rows too.
    let actor = null;
    try { actor = await authenticateSignShopSession(base44, body?.session_token); }
    catch { actor = await base44.auth.me().catch(() => null); }
    if (!actor?.id && !actor?.email) return Response.json({ error: 'Authentication required.' }, { status: 401 });
    const idempotencyKey = String(body?.idempotency_key || '').trim();
    const revision = body?.revision && typeof body.revision === 'object' ? body.revision : {};
    const builderProductId = String(revision?.builder_product_id || '').trim();
    const estimateId = String(revision?.estimate_id || '').trim();

    if (!idempotencyKey || !builderProductId || !estimateId) {
      return Response.json({ error: 'Builder Product, estimate, and idempotency key are required.' }, { status: 400 });
    }
    if (!ALLOWED_REASONS.has(String(revision?.reason || ''))) {
      return Response.json({ error: 'This function only records supported Builder pricing revisions.' }, { status: 400 });
    }

    const RevisionService = base44.asServiceRole.entities.BuilderPriceRevision;

    let matches = await RevisionService.filter({
      builder_product_id: builderProductId,
      idempotency_key: idempotencyKey,
    });
    const existing = canonicalRevision(matches || []);
    if (existing) {
      assertSameOperation(existing, revision);
      return Response.json({ revision: existing, reused: true });
    }

    // Before creating immutable pricing history, verify the caller-supplied IDs
    // still describe a real Product attached to this Estimate. Existing audit
    // retries above remain reusable even if the Product is removed later.
    const [builder, estimate] = await Promise.all([
      base44.entities.BuilderProduct.get(builderProductId).catch(() => null),
      base44.entities.AllInOneEstimate.get(estimateId).catch(() => null),
    ]);
    if (!builder?.id) return Response.json({ error: 'Builder Product could not be verified for this pricing revision.' }, { status: 404 });
    if (!estimate?.id) return Response.json({ error: 'Estimate could not be verified for this pricing revision.' }, { status: 404 });
    if (String(builder.estimate_id || '') !== estimateId) {
      return Response.json({ error: 'Builder Product does not belong to the supplied Estimate.' }, { status: 409 });
    }
    const estimateLine = (estimate.line_items || []).find((line: any) => String(line?.builder_product_id || '') === builderProductId);
    if (!estimateLine) {
      return Response.json({ error: 'Builder Product is no longer attached to the supplied Estimate.' }, { status: 409 });
    }

    const allRows = await RevisionService.filter({ builder_product_id: builderProductId });
    const revisionNumber = Math.max(0, ...(allRows || []).map((row) => num(row?.revision_number))) + 1;
    // Only schema-declared revision fields may persist — and any previous_*
    // snapshot fields are derived from the live Product, never caller input,
    // so the immutable audit row reflects server-verified state.
    const ALLOWED_REVISION_FIELDS = ['builder_snapshot_after','builder_snapshot_before','changed_parts','new_customer_price','new_total_cost','notes','previous_customer_price','previous_total_cost','price_snapshot_after','price_snapshot_before','reason','actor','accepted_by','created_by_user'];
    const cleanRevision: Record<string, unknown> = {};
    for (const key of ALLOWED_REVISION_FIELDS) {
      if (Object.prototype.hasOwnProperty.call(revision, key)) cleanRevision[key] = revision[key];
    }
    const created = await RevisionService.create({
      ...cleanRevision,
      builder_product_id: builderProductId,
      estimate_id: estimateId,
      idempotency_key: idempotencyKey,
      revision_number: revisionNumber,
      reason: revision.reason,
    });

    // Base44 does not expose a unique database constraint here. Re-read after
    // create so simultaneous Builder price-acceptance retries converge on one immutable row.
    await new Promise((resolve) => setTimeout(resolve, 50));
    matches = await RevisionService.filter({
      builder_product_id: builderProductId,
      idempotency_key: idempotencyKey,
    });
    const canonical = canonicalRevision(matches || []) || created;
    assertSameOperation(canonical, revision);

    if (canonical?.id && created?.id && canonical.id !== created.id) {
      const createdVersion = String(created.updated_date || '').trim();
      if (!createdVersion) {
        throw new Error('A duplicate Builder price revision was detected, but the losing row has no version metadata. No uncertain revision was deleted.');
      }
      const deleted = await RevisionService.deleteMany({
        id: created.id,
        builder_product_id: builderProductId,
        idempotency_key: idempotencyKey,
        updated_date: createdVersion,
      });
      if (!deleted || deleted.deleted !== 1) {
        throw new Error('A duplicate Builder price revision changed before cleanup. No uncertain revision was deleted; reload the Builder pricing history before retrying.');
      }
      return Response.json({ revision: canonical, reused: true, concurrent_duplicate_discarded: true });
    }

    const settled = await settleRevisionNumber(RevisionService, builderProductId, canonical || created);
    return Response.json({ revision: settled, reused: false });
  } catch (error) {
    const status = Number(error?.status || error?.statusCode || 500);
    const safeStatus = [400, 401, 403, 404, 409, 429, 503].includes(status) ? status : 500;
    console.error('ensureBuilderPriceRevision error:', error?.message || error);
    return Response.json({
      error: safeStatus === 500 ? 'Builder price revision could not be recorded safely.' : error.message,
    }, { status: safeStatus });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';

const ALLOWED_FIELDS = new Set([
  'company_name',
  'company_phone',
  'contact_first_name',
  'contact_last_name',
  'contact_email',
  'contact_office_phone',
  'contact_office_ext',
  'billing_address_1',
  'billing_city',
  'billing_state',
  'billing_postal_code',
  'terms',
  'pricing_tier',
]);

const CUSTOMER_REFERENCE_ENTITIES = [
  'VinylProject',
  'Order',
  'ChannelLetterInstallation',
  'WorkOrder',
  'MaintenanceProject',
  'Project',
  'CNCProject',
  'MetalProject',
  'FoundationProject',
  'AllInOneEstimate',
  'LaserProject',
  'CustomerNote',
  'BrickStoneProject',
  'CustomerSummary',
];

const clean = (value: unknown) => String(value || '').trim();

const normalize = (value: any): any => {
  if (Array.isArray(value)) return value.map(normalize);
  if (value && typeof value === 'object') {
    return Object.keys(value).sort().reduce((result: any, key) => {
      if (value[key] !== undefined) result[key] = normalize(value[key]);
      return result;
    }, {});
  }
  return value;
};

const sameTarget = (row: any = {}, target: any = {}) => {
  const projected: any = {};
  for (const key of Object.keys(target)) projected[key] = row?.[key];
  return JSON.stringify(normalize(projected)) === JSON.stringify(normalize(target));
};

const canonicalRow = (rows: any[] = []) => rows.slice().sort((a, b) => {
  const aTime = Date.parse(a?.created_date || a?.updated_date || '') || 0;
  const bTime = Date.parse(b?.created_date || b?.updated_date || '') || 0;
  if (aTime !== bTime) return aTime - bTime;
  return String(a?.id || '').localeCompare(String(b?.id || ''));
})[0] || null;

async function customerReference(base44: any, customerId: string) {
  for (const entityName of CUSTOMER_REFERENCE_ENTITIES) {
    const entity = base44.asServiceRole.entities[entityName];
    if (!entity?.filter) continue;
    const rows = await entity.filter({ customer_id: customerId });
    if ((rows || []).length) return entityName;
  }
  return '';
}

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const body = await req.json().catch(() => ({}));
    await authenticateSignShopSession(base44, body?.session_token);
    const creationKey = clean(body?.creation_key);
    const input = body?.customer && typeof body.customer === 'object' ? body.customer : {};
    if (!creationKey || creationKey.length > 256) {
      return Response.json({ error: 'A valid Customer creation key is required.' }, { status: 400 });
    }

    const customer: any = {};
    for (const [key, value] of Object.entries(input)) {
      if (ALLOWED_FIELDS.has(key)) customer[key] = value;
    }
    customer.company_name = clean(customer.company_name);
    customer.pricing_tier = Number.isFinite(Number(customer.pricing_tier)) ? Number(customer.pricing_tier) : 1;
    customer.customer_status = 'prospect';
    customer.is_active = true;
    customer.creation_request_key = creationKey;

    if (!customer.company_name) {
      return Response.json({ error: 'Customer company name is required.' }, { status: 400 });
    }

    const CustomerUser = base44.entities.Customer;
    const CustomerService = base44.asServiceRole.entities.Customer;
    const readKeyedRows = async () => {
      const rows = await CustomerService.filter({ creation_request_key: creationKey });
      if (!Array.isArray(rows)) {
        throw Object.assign(new Error('Customer creation receipt lookup did not return a verifiable record list.'), { statusCode: 409 });
      }
      return rows;
    };
    const validateRows = (rows: any[] = [], { allowMultiple = false } = {}) => {
      const mismatches = rows.filter((row: any) => !sameTarget(row, customer));
      if (mismatches.length) {
        throw Object.assign(new Error('This Customer creation receipt is already associated with different Customer data. No Customer was changed.'), { statusCode: 409 });
      }
      if (!allowMultiple && rows.length > 1) {
        throw Object.assign(new Error('Multiple Customers already share this creation receipt. No uncertain Customer was deleted; review the duplicate Customers before retrying.'), { statusCode: 409 });
      }
      return canonicalRow(rows);
    };

    let rows = await readKeyedRows();
    const existing = validateRows(rows);
    if (existing?.id) return Response.json({ customer: existing, reused: true });

    let created;
    try {
      created = await CustomerService.create(customer);
    } catch (createError) {
      try {
        rows = await readKeyedRows();
      } catch (verificationError) {
        throw Object.assign(new Error(
          `Customer create response was unavailable and its recovery lookup also failed. Do not retry blindly; reload Customers first. ${verificationError?.message || ''}`.trim()
        ), { statusCode: 409 });
      }
      const recovered = validateRows(rows);
      if (recovered?.id) return Response.json({ customer: recovered, reused: true, recovered_after_create_error: true });
      throw createError;
    }

    await new Promise((resolve) => setTimeout(resolve, 50));
    try {
      rows = await readKeyedRows();
    } catch (verificationError) {
      throw Object.assign(new Error(
        `Customer was created, but its concurrent verification read failed. Do not retry blindly; reload Customers first. ${verificationError?.message || ''}`.trim()
      ), { statusCode: 409 });
    }
    const canonical = validateRows(rows, { allowMultiple: true }) || created;

    if (rows.length > 1 && canonical?.id === created?.id) {
      return Response.json({ error: 'A concurrent Customer was created with the same creation receipt after this request became canonical. The canonical Customer was preserved and no uncertain concurrent row was deleted; review the duplicate Customers before continuing.' }, { status: 409 });
    }

    if (canonical?.id && created?.id && canonical.id !== created.id) {
      const losingRows = await CustomerService.filter({ id: created.id });
      if (!Array.isArray(losingRows) || losingRows.length > 1) {
        return Response.json({ error: 'The losing duplicate Customer could not be re-read safely. No uncertain Customer was deleted.' }, { status: 409 });
      }
      const losing = losingRows[0] || null;
      if (losing?.id) {
        const referencedBy = await customerReference(base44, losing.id);
        if (referencedBy) {
          return Response.json({
            error: `A simultaneous duplicate Customer was detected, but the losing row is already referenced by ${referencedBy}. No Customer was deleted.`,
          }, { status: 409 });
        }
        const losingVersion = String(losing.updated_date || '').trim();
        if (!losingVersion) {
          return Response.json({ error: 'The losing duplicate Customer has no version metadata. No uncertain Customer was deleted.' }, { status: 409 });
        }
        let deleted;
        try {
          deleted = await CustomerService.deleteMany({
            id: losing.id,
            creation_request_key: creationKey,
            updated_date: losingVersion,
          });
        } catch (deleteError) {
          const afterError = await CustomerService.filter({ id: losing.id }).catch(() => null);
          if (!Array.isArray(afterError) || afterError.length !== 0) throw deleteError;
          deleted = { deleted: 1 };
        }
        if (!deleted || deleted.deleted !== 1) {
          const afterDelete = await CustomerService.filter({ id: losing.id }).catch(() => null);
          if (!Array.isArray(afterDelete) || afterDelete.length !== 0) {
            return Response.json({ error: 'The losing duplicate Customer changed before cleanup. No uncertain Customer was deleted; reload before retrying.' }, { status: 409 });
          }
        }
      }
      return Response.json({ customer: canonical, reused: true, concurrent_duplicate_discarded: true });
    }

    return Response.json({ customer: canonical, reused: false });
  } catch (error) {
    const status = Number(error?.status || error?.statusCode || 500);
    const safeStatus = [400, 401, 403, 404, 409, 429, 503].includes(status) ? status : 500;
    console.error('ensureNewCustomer error:', error?.message || error);
    return Response.json({
      error: safeStatus === 500 ? 'Customer could not be created safely.' : error.message,
    }, { status: safeStatus });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.46';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';

const MODULE_PROJECT_ENTITIES: Record<string, string> = {
  channel_letter_installation: 'ChannelLetterInstallation',
  foundation: 'FoundationProject',
  brick_stone: 'BrickStoneProject',
  paint: 'Project',
  laser: 'LaserProject',
  cnc: 'CNCProject',
  metal_fabrication: 'MetalProject',
  vinyl: 'VinylProject',
  sign_maintenance: 'MaintenanceProject',
};
const ALLOWED_MODULES = new Set(Object.keys(MODULE_PROJECT_ENTITIES));

const PAGE_SIZE = 500;
const VERIFY_LIMIT = 50000;
const MAX_CAS_ATTEMPTS = 12;

const norm = (value: unknown) => String(value || '').trim().toLowerCase();
const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
const summaryKeyFor = (normalizedName: string) => `customer_summary:v1:${normalizedName}`;
const projectLinkKey = (link: any) => `${String(link?.module || '')}::${String(link?.project_id || '')}`;

const canonicalRow = (rows: any[] = []) => rows.slice().sort((a, b) => {
  const aTime = Date.parse(a?.created_date || a?.updated_date || '') || 0;
  const bTime = Date.parse(b?.created_date || b?.updated_date || '') || 0;
  if (aTime !== bTime) return aTime - bTime;
  return String(a?.id || '').localeCompare(String(b?.id || ''));
})[0] || null;

function cleanLink(input: any) {
  const module = String(input?.module || '').trim();
  const projectId = String(input?.project_id || '').trim();
  if (!ALLOWED_MODULES.has(module) || !projectId) return null;
  return {
    module,
    project_id: projectId,
    project_name: String(input?.project_name || ''),
  };
}

function mergeLinks(base: any[] = [], additions: any[] = [], requested: any = null) {
  const map = new Map<string, any>();
  for (const raw of Array.isArray(base) ? base : []) {
    const link = cleanLink(raw);
    if (!link) continue;
    const key = projectLinkKey(link);
    if (!map.has(key)) map.set(key, link);
  }
  for (const raw of Array.isArray(additions) ? additions : []) {
    const link = cleanLink(raw);
    if (!link) continue;
    const key = projectLinkKey(link);
    if (!map.has(key)) map.set(key, link);
  }
  const requestedLink = cleanLink(requested);
  if (requestedLink) map.set(projectLinkKey(requestedLink), requestedLink);
  return [...map.values()];
}

function sameLinks(a: any[] = [], b: any[] = []) {
  if ((a || []).length !== (b || []).length) return false;
  return (a || []).every((link, index) => {
    const other = (b || [])[index];
    return link?.module === other?.module &&
      link?.project_id === other?.project_id &&
      String(link?.project_name || '') === String(other?.project_name || '');
  });
}

async function loadCandidates(Summary: any, normalizedName: string, summaryKey: string) {
  const matches: any[] = [];
  let skip = 0;
  while (skip < VERIFY_LIMIT) {
    const page = await Summary.list('created_date', PAGE_SIZE, skip);
    if (!Array.isArray(page)) {
      throw new Error('Customer Summary records could not be verified safely.');
    }
    for (const row of page) {
      if (norm(row?.client_name) === normalizedName || String(row?.summary_key || '') === summaryKey) {
        matches.push(row);
      }
    }
    if (page.length < PAGE_SIZE) return matches;
    skip += PAGE_SIZE;
  }
  throw new Error(`Customer Summary verification exceeded the ${VERIFY_LIMIT.toLocaleString()}-record safety limit.`);
}

async function getFresh(Summary: any, id: string) {
  try {
    return await Summary.get(id);
  } catch {
    return null;
  }
}

function isNotFoundError(error: any) {
  return Number(error?.response?.status || error?.status || error?.statusCode || 0) === 404;
}

async function getFreshForDeleteVerification(Summary: any, id: string) {
  try {
    return (await Summary.get(id)) || null;
  } catch (error) {
    if (isNotFoundError(error)) return null;
    throw new Error(`Duplicate Customer Summary deletion could not verify whether the row still exists. ${error?.message || ''}`.trim());
  }
}

async function casSet(Summary: any, row: any, patch: any) {
  if (!row?.id || !row?.updated_date) {
    throw new Error('Customer Summary version metadata is incomplete; concurrent-safe update was blocked.');
  }
  const result = await Summary.updateMany(
    { id: row.id, updated_date: row.updated_date },
    { $set: patch },
  );
  if (!result || typeof result.updated !== 'number') {
    throw new Error('Customer Summary conditional-update result could not be verified.');
  }
  return result.updated === 1;
}

async function claimSummaryKey(Summary: any, row: any, summaryKey: string) {
  for (let attempt = 0; attempt < MAX_CAS_ATTEMPTS; attempt += 1) {
    const current = attempt === 0 ? row : await getFresh(Summary, row.id);
    if (!current) throw new Error('Customer Summary disappeared while its concurrency key was being established.');
    const currentKey = String(current?.summary_key || '');
    if (currentKey === summaryKey) return current;
    if (currentKey && currentKey !== summaryKey) {
      throw new Error('Customer Summary is already associated with a different concurrency key.');
    }
    if (await casSet(Summary, current, { summary_key: summaryKey })) {
      return (await getFresh(Summary, current.id)) || { ...current, summary_key: summaryKey };
    }
  }
  throw new Error('Customer Summary concurrency key could not be established because the row kept changing.');
}

async function mergeIntoCanonical({
  Summary,
  canonicalId,
  summaryKey,
  requestedLink,
  additions = [],
  estimateNumber = '',
}: any) {
  for (let attempt = 0; attempt < MAX_CAS_ATTEMPTS; attempt += 1) {
    const current = await getFresh(Summary, canonicalId);
    if (!current) throw new Error('Canonical Customer Summary disappeared during merge.');
    const currentKey = String(current?.summary_key || '');
    if (currentKey && currentKey !== summaryKey) {
      throw new Error('Canonical Customer Summary changed to a different concurrency key.');
    }

    const links = mergeLinks(current?.linked_projects || [], additions, requestedLink);
    const desiredEstimateNumber = String(estimateNumber || current?.estimate_number || '');
    const noChange = currentKey === summaryKey &&
      desiredEstimateNumber === String(current?.estimate_number || '') &&
      sameLinks(links, current?.linked_projects || []);
    if (noChange) return current;

    const won = await casSet(Summary, current, {
      summary_key: summaryKey,
      linked_projects: links,
      estimate_number: desiredEstimateNumber,
    });
    if (!won) continue;

    const verified = await getFresh(Summary, canonicalId);
    if (!verified) throw new Error('Customer Summary update succeeded but the row could not be re-read.');
    const requestedKey = projectLinkKey(requestedLink);
    const hasRequested = (verified?.linked_projects || []).some((link: any) =>
      projectLinkKey(link) === requestedKey &&
      String(link?.project_name || '') === String(requestedLink?.project_name || '')
    );
    if (hasRequested) return verified;
  }
  throw new Error('Customer Summary could not converge because another save kept changing it.');
}

function duplicateIsSafeToDelete(row: any, userId: string, summaryKey: string, normalizedName: string) {
  if (!row?.id || String(row?.summary_key || '') !== summaryKey) return false;
  if (norm(row?.client_name) !== normalizedName) return false;
  if (String(row?.created_by_id || '') !== userId) return false;
  if (String(row?.notes || '').trim()) return false;
  if (String(row?.customer_id || '').trim()) return false;
  if (Number(row?.tier_number ?? 1) !== 1) return false;
  return true;
}

async function deleteVerified(Summary: any, row: any) {
  const version = String(row?.updated_date || '').trim();
  const summaryKey = String(row?.summary_key || '').trim();
  if (!row?.id || !version || !summaryKey) {
    throw new Error('Duplicate Customer Summary is missing identity/version metadata required for safe deletion.');
  }

  let result;
  try {
    result = await Summary.deleteMany({
      id: row.id,
      summary_key: summaryKey,
      updated_date: version,
    });
  } catch (error) {
    const stillThere = await getFreshForDeleteVerification(Summary, row.id);
    if (stillThere) throw error;
    return;
  }

  if (!result || typeof result.deleted !== 'number') {
    const stillThere = await getFreshForDeleteVerification(Summary, row.id);
    if (!stillThere) return;
    throw new Error('Duplicate Customer Summary conditional-delete result could not be verified.');
  }
  if (result.deleted !== 1) {
    const stillThere = await getFreshForDeleteVerification(Summary, row.id);
    if (!stillThere) return;
    throw new Error('Duplicate Customer Summary changed before deletion. The newer row was preserved.');
  }

  const stillThere = await getFreshForDeleteVerification(Summary, row.id);
  if (stillThere) throw new Error('Duplicate Customer Summary delete returned successfully but the row still exists.');
}

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const body = await req.json().catch(() => ({}));
    // Fall back to auth.me() when no sign-shop session token is supplied so
    // request-context users can still complete the guarded summary write.
    let user = null;
    try { user = await authenticateSignShopSession(base44, body?.session_token); }
    catch { user = await base44.auth.me().catch(() => null); }
    if (!user?.id) return Response.json({ error: 'Unauthorized' }, { status: 401 });
    const clientName = String(body?.client_name || '').trim();
    const normalizedName = norm(clientName);
    const module = String(body?.module || '').trim();
    const projectId = String(body?.project_id || '').trim();
    if (!clientName || !normalizedName || !ALLOWED_MODULES.has(module) || !projectId) {
      return Response.json({ error: 'Client name, supported module, and project id are required.' }, { status: 400 });
    }

    // A Customer Summary link is convenience metadata, but it must still point
    // at a real source project the authenticated caller can read. Never trust a
    // caller-supplied project name/client identity for an immutable relationship.
    const sourceEntityName = MODULE_PROJECT_ENTITIES[module];
    const SourceProject = base44.entities[sourceEntityName];
    const sourceProject = await SourceProject?.get(projectId).catch(() => null);
    if (!sourceProject?.id) {
      return Response.json({ error: 'The source estimator project could not be verified before updating the Customer Summary.' }, { status: 404 });
    }
    if (norm(sourceProject.client_name) !== normalizedName) {
      return Response.json({ error: 'The source estimator project belongs to a different client. Customer Summary was not changed.' }, { status: 409 });
    }

    const requestedLink = {
      module,
      project_id: projectId,
      project_name: String(sourceProject.project_name || ''),
    };
    const estimateNumber = String(sourceProject.estimate_number || '').trim();
    const summaryKey = summaryKeyFor(normalizedName);
    const Summary = base44.asServiceRole.entities.CustomerSummary;

    let candidates = await loadCandidates(Summary, normalizedName, summaryKey);
    const keyCollisions = candidates.filter((row: any) =>
      String(row?.summary_key || '') === summaryKey && norm(row?.client_name) !== normalizedName
    );
    if (keyCollisions.length) {
      return Response.json({ error: 'Customer Summary concurrency key is already associated with a different client.' }, { status: 409 });
    }

    let canonical = canonicalRow(candidates.filter((row: any) => norm(row?.client_name) === normalizedName));
    let createdByThisRequest: any = null;

    if (!canonical) {
      let createError: any = null;
      try {
        createdByThisRequest = await Summary.create({
          summary_name: clientName,
          client_name: clientName,
          summary_key: summaryKey,
          estimate_number: estimateNumber,
          tier_number: 1,
          linked_projects: [requestedLink],
        });
      } catch (error) {
        createError = error;
      }

      await sleep(50);
      candidates = await loadCandidates(Summary, normalizedName, summaryKey);
      canonical = canonicalRow(candidates.filter((row: any) => norm(row?.client_name) === normalizedName));
      if (!canonical) {
        if (createError) throw createError;
        canonical = createdByThisRequest;
      }
      if (!canonical?.id) throw new Error('Customer Summary create could not be verified.');
    }

    canonical = await claimSummaryKey(Summary, canonical, summaryKey);

    // Merge the requested project first. This is a real compare-and-swap because
    // updateMany only succeeds when updated_date still matches the snapshot used
    // to compute the new linked_projects array.
    canonical = await mergeIntoCanonical({
      Summary,
      canonicalId: canonical.id,
      summaryKey,
      requestedLink,
      estimateNumber,
    });

    // Re-read a few times so simultaneous first creates using the same deterministic
    // key can converge. Only function-keyed rows are considered duplicates; old
    // historical summaries without this key are never deleted automatically.
    for (let round = 0; round < 3; round += 1) {
      if (round > 0) await sleep(40);
      candidates = await loadCandidates(Summary, normalizedName, summaryKey);
      const keyedDuplicates = candidates.filter((row: any) =>
        row?.id !== canonical.id && String(row?.summary_key || '') === summaryKey
      );
      if (!keyedDuplicates.length) break;

      for (const duplicate of keyedDuplicates) {
        const freshDuplicate = await getFresh(Summary, duplicate.id);
        if (!freshDuplicate) continue;
        if (norm(freshDuplicate?.client_name) !== normalizedName) {
          throw new Error('Customer Summary duplicate changed client identity during convergence.');
        }

        canonical = await mergeIntoCanonical({
          Summary,
          canonicalId: canonical.id,
          summaryKey,
          requestedLink,
          additions: freshDuplicate?.linked_projects || [],
          estimateNumber,
        });

        if (!duplicateIsSafeToDelete(freshDuplicate, String(user.id), summaryKey, normalizedName)) {
          throw new Error('A duplicate Customer Summary contains protected user data and was not deleted automatically.');
        }
        await deleteVerified(Summary, freshDuplicate);
      }
    }

    const finalSummary = await mergeIntoCanonical({
      Summary,
      canonicalId: canonical.id,
      summaryKey,
      requestedLink,
      estimateNumber,
    });

    return Response.json({ summary: finalSummary, reused: !createdByThisRequest });
  } catch (error) {
    const status = Number(error?.status || error?.statusCode || 500);
    const safeStatus = [400, 401, 403, 404, 409, 429, 503].includes(status) ? status : 500;
    console.error('ensureCustomerSummary error:', error?.message || error);
    return Response.json({
      error: safeStatus === 500 ? 'Customer Summary could not be updated safely.' : error.message,
    }, { status: safeStatus });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import {
  CRM_EVENT_TYPES,
  CRM_ACTIVITY_FIELDS,
  CRM_CUSTOMER_FIELDS,
  ESTIMATE_QUEUE_FIELDS,
  GENERAL_TASK_FIELDS,
  MY_WORKFLOW_USER_FIELDS,
  QUOTE_DEFAULTS_FIELDS,
  SAVED_VIEW_FIELDS,
  projectCrmActivity,
  projectCrmCustomer,
  projectEstimate,
  projectGeneralTask,
  projectQuoteDefaults,
  projectSettingRecord,
  projectWorkflowUser,
  scopeSavedViewsForLens,
  scopeSavedViewsForPage,
  queueFeedCacheKey,
} from '../../shared/queueFeedModel.mjs';

// Queue feed — one composed, projected payload per queue page instead of N
// parallel entity reads from the browser (masterplan M-03). Every surface
// returns `items` (the page's row set, allowlist-projected) plus the scoped
// extras the page mounts with, so a queue mount is ONE function call on one
// caller budget rather than a boardFeed pull plus several gateway reads.
//
//   feed=product_queue (default)
//     items      — the WorkOrder projection the product queue pages need and
//                  nothing else (~70-80% smaller than the board projection,
//                  which still carries ~150 top-level fields and whole
//                  product sub-documents). QUEUE_WO_FIELDS covers every field
//                  flattenQueueRows, queueCountersModel.moduleKeyForRow, the
//                  ProductQueue row chrome AND the write paths mounted rows
//                  drive (deposit gate reads deposit_required/invoiced/
//                  amount; notify context reads estimator/total/balance_due).
//     saved_views — SavedQueueView rows scoped to {queue_lens, session
//                  owner} — the same set loadSavedQueueViews returns.
//     settings   — { product_stage_mode } GlobalSettings record.
//
//   feed=crm_events
//     items      — OpportunityActivity rows whose event_type is in the CRM
//                  taxonomy (server-side $in — audit rows never cross the
//                  wire), projected to the fields CrmEventsQueue reads.
//     customers  — the company datalist set, {id, company_name, name}.
//
//   feed=estimate_queue
//     items      — AllInOneEstimate rows projected to the queue's columns +
//                  trash-lifecycle CAS fields + the estimateMatchesSearch
//                  haystack (line_items[] survives projected to the search
//                  subfields — full line blobs never leave the server).
//     quote_defaults — the {config_name:"default"} QuoteDefaults row.
//     saved_views — page-axis views when page_key is passed.
//
//   feed=my_workflow
//     items      — GeneralTask rows where completed:false, projected to every
//                  declared field and sorted by created_date to match the
//                  gateway read the page ran. The work-order half of the page
//                  still comes from the shared boardFeed snapshot — folding it
//                  in would duplicate a whole-table pull for heavy fields the
//                  queue projections deliberately strip (notes, sip_checklist).
//     users      — the AuthorizedEmail assignee roster projected to the five
//                  fields the pickers read (tight allowlist — the entity's
//                  credential/session fields never leave the backend).
//     dropdown_conditions — GlobalSettings('dropdownConditions') record.
//     task_descriptions — GlobalSettings('salesTaskDescriptions') record.
//     Nothing in this feed is owner-scoped, so its isolate-cache key drops
//     the owner segment entirely — every staff session shares the entry.
//
// Common controls: `since` (updated_date delta cursor, server-side $gte),
// `limit` (caps items; capped responses keep next_cursor honest), `include`
// (subset of the feed's extras; default = all of them), `items:false`
// (extras-only call — no table scan), `queue_lens`/`page_key`/`module_key`
// lenses. next_cursor = max updated_date scanned; rows scan oldest→newest so
// a limited pull resumes gap-free and clients dedupe by id.
// Saved-view owner scoping uses the AUTHENTICATED session email, never the
// request's owner_email — per-user rows must never cross owners.
// Read scope matches boardFeed: a valid staff session is required — the
// service-role read must not reopen what the entity RLS lockdown closed.

const QUEUE_WO_FIELDS = [
  'id', 'created_date', 'updated_date',
  'title', 'client_name', 'customer_id', 'contact_email', 'opportunity_id',
  'corbridge_invoice_number',
  'current_stage', 'priority', 'assigned_to', 'due_date', 'project_install_date',
  'completed', 'deleted',
  // Module ownership — moduleKeyForRow's WO fallback chain, first non-blank wins.
  'module_key', 'project_type', 'order_type', 'module', 'type',
  // Queue filter columns (QueueFilterBar: salesperson / entered_by) + enteredBy.
  'sales_rep', 'salesperson', 'salesperson_email',
  'created_by', 'entered_by',
  // Order-level rush signals flattenQueueRows folds into the row's rush flag.
  'is_rush', 'rush', 'order_priority',
  // Write/notify paths mounted rows drive: deposit gate (depositGate.js) and
  // buildNotifyContext fallbacks. Without these a projected snapshot would
  // silently bypass the deposit warning and empty notify placeholders.
  'deposit_required', 'deposit_invoiced', 'deposit_amount',
  'estimator', 'total', 'balance_due',
  'products',
];

const QUEUE_PRODUCT_FIELDS = [
  'id', 'product_name', 'description', 'client_product_name', 'quantity',
  'product_type', 'category', 'module_key',
  'operational_status', 'operational_substatus', 'customer_facing_status',
  'operational_status_changed_at',
  'fulfillment_state', 'fulfillment_method',
  'proof_status', 'proof_version', 'proof_approved_version',
  'proof_file_url', 'proof_file_name',
  'design_due_date', 'product_due_date', 'hard_due_date',
  'designer', 'assigned_to', 'responsibility', 'responsibility_color',
  'priority', 'queue_priority', 'priority_label',
  // Product-level rush signals + quick tags.
  'is_rush', 'rush', 'quick_tags',
  // CoreBridge filter keys (machine / part columns).
  'machine', 'machine_name', 'assigned_machine', 'part', 'part_name',
  // Per-product crew/credit spellings some imported rows carry.
  'salesperson', 'entered_by',
  'builder_product_id',
];

// Heavy product sub-documents the queue never renders. The allowlist already
// excludes them; the explicit strip is a guard so a future field-list edit
// can't silently re-inflate the payload.
const PRODUCT_HEAVY_FIELDS = ['notes', 'status_history', 'conversion_events'];
const PRODUCT_HEAVY_PREFIXES = ['smartsheet_'];

// WO module ownership fallback chain — same order moduleKeyForRow uses.
const WO_MODULE_KEYS = ['module_key', 'project_type', 'order_type', 'module', 'type'];

// One 5k page pulls the whole active table in a single entity_list call
// (~2-5s) instead of sequential 500-row pages — same budget math as boardFeed.
const PAGE_SIZE = 5000;
const MAX_ROWS = 20000;
const MAX_LIMIT = 20000;
const MAX_MODULE_KEY = 120;
const MAX_LENS = 80;
const MAX_OWNER = 200;
// SavedQueueView scopes are small by design; the gateway path capped them at
// the same bound (loadRows maxRows: 2000), so parity holds.
const MAX_SAVED_VIEWS = 2000;
const SETTINGS_KEY_STAGE_MODE = 'productStatusDrivesStage';
const SETTINGS_KEY_DROPDOWN_CONDITIONS = 'dropdownConditions';
const SETTINGS_KEY_TASK_DESCRIPTIONS = 'salesTaskDescriptions';

const FEED_NAMES = new Set(['product_queue', 'crm_events', 'estimate_queue', 'my_workflow']);
// Which extras each feed can compose. `include` narrows this set; when the
// caller does not pass include, all of the feed's extras are returned.
const FEED_EXTRAS = {
  product_queue: ['saved_views', 'settings'],
  crm_events: ['customers'],
  estimate_queue: ['quote_defaults', 'saved_views'],
  my_workflow: ['users', 'dropdown_conditions', 'task_descriptions'],
};

function bad(message: string) {
  return Object.assign(new Error(message), { status: 400 });
}

function cleanSince(value: unknown) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const ms = Date.parse(raw);
  if (!Number.isFinite(ms)) throw bad('Feed cursor is invalid.');
  return new Date(ms).toISOString();
}

function cleanLimit(value: unknown) {
  if (value == null || value === '') return 0;
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) throw bad('Feed limit is invalid.');
  return Math.min(Math.floor(n), MAX_LIMIT);
}

function cleanModuleKey(value: unknown) {
  const raw = String(value || '').trim().toLowerCase();
  if (!raw) return '';
  if (raw.length > MAX_MODULE_KEY) throw bad('Feed module_key is invalid.');
  return raw;
}

function cleanFeed(value: unknown) {
  const raw = String(value || '').trim().toLowerCase();
  if (!raw) return 'product_queue';
  if (!FEED_NAMES.has(raw)) throw bad('This feed cannot be read here.');
  return raw;
}

function cleanLens(value: unknown) {
  const raw = String(value || '').trim();
  if (raw.length > MAX_LENS) throw bad('Feed queue_lens is invalid.');
  return raw;
}

function cleanPageKey(value: unknown) {
  const raw = String(value || '').trim();
  if (raw.length > MAX_LENS) throw bad('Feed page_key is invalid.');
  return raw;
}

function cleanOwner(value: unknown) {
  const raw = String(value || '').trim().toLowerCase();
  if (raw.length > MAX_OWNER) throw bad('Feed owner_email is invalid.');
  return raw;
}

function cleanInclude(value: unknown, feed: string) {
  const allowed = new Set(FEED_EXTRAS[feed] || []);
  if (value == null || value === '') return [...allowed];
  const list = Array.isArray(value) ? value : String(value).split(',');
  const out = [...new Set(list.map((v) => String(v || '').trim().toLowerCase()).filter(Boolean))];
  for (const name of out) {
    if (!allowed.has(name)) throw bad(`Feed extra is not available here: ${name}`);
  }
  return out;
}

const norm = (v: unknown) => String(v || '').trim().toLowerCase();

function woModuleKey(wo: any) {
  for (const key of WO_MODULE_KEYS) {
    const v = norm(wo?.[key]);
    if (v) return v;
  }
  return '';
}

// Product module ownership mirrors moduleKeyForRow: the product's own
// module_key wins, the WO's resolved module is the fallback for products
// that never got stamped at conversion.
function productModuleKey(product: any, woKey: string) {
  return norm(product?.module_key) || woKey;
}

function projectProduct(product: any) {
  if (!product || typeof product !== 'object') return product;
  const out: any = {};
  for (const field of QUEUE_PRODUCT_FIELDS) out[field] = product[field];
  for (const field of PRODUCT_HEAVY_FIELDS) delete out[field];
  for (const key of Object.keys(out)) {
    if (PRODUCT_HEAVY_PREFIXES.some((p) => key.startsWith(p))) delete out[key];
  }
  return out;
}

function projectWorkOrder(row: any, wantedModule: string) {
  if (!row || typeof row !== 'object') return row;
  const out: any = {};
  for (const field of QUEUE_WO_FIELDS) out[field] = row[field];
  const woKey = woModuleKey(row);
  const products = Array.isArray(row.products) ? row.products : [];
  if (!wantedModule) {
    out.products = products.map(projectProduct);
    return out;
  }
  // Module lens — keep only products whose resolved module matches; a WO
  // left with no contributing products is dropped by the caller (it has no
  // queue rows to show).
  const kept = products.filter((p) => productModuleKey(p, woKey) === wantedModule);
  if (!kept.length) return null;
  out.products = kept.map(projectProduct);
  return out;
}

// Module-scope result cache — Deno isolates are reused across invocations,
// so a burst of identical pulls (many staff tabs opening the same queue at
// once) collapses to one upstream read set instead of one table scan per
// tab. Keyed by feed+lens+pageKey+session-owner+include+module so per-user
// payloads (own saved views) never cross owners and per-lens extras never
// cross queues. Delta pulls (since) and limited pulls are never cached; the
// cached payload keeps its own generated_at/next_cursor so the caller's
// resume cursor still covers the gap.
const feedCache = new Map<string, { payload: any; expires: number; at: number }>();
const FEED_CACHE_TTL_MS = 30_000;
const FEED_CACHE_MAX_KEYS = 40;

function feedCacheGet(key: string) {
  const hit = feedCache.get(key);
  if (!hit) return null;
  if (hit.expires <= Date.now()) {
    feedCache.delete(key);
    return null;
  }
  return hit.payload;
}

function feedCacheSet(key: string, payload: any) {
  if (feedCache.size >= FEED_CACHE_MAX_KEYS) {
    const now = Date.now();
    for (const [k, v] of feedCache) {
      if (v.expires <= now) feedCache.delete(k);
    }
    if (feedCache.size >= FEED_CACHE_MAX_KEYS) {
      // Evict the oldest entry — a full cache must never grow unbounded.
      let oldestKey: string | null = null;
      let oldestAt = Infinity;
      for (const [k, v] of feedCache) {
        if (v.at < oldestAt) { oldestAt = v.at; oldestKey = k; }
      }
      if (oldestKey !== null) feedCache.delete(oldestKey);
    }
  }
  feedCache.set(key, { payload, expires: Date.now() + FEED_CACHE_TTL_MS, at: Date.now() });
}

// Set false permanently for the isolate if a projected filter is rejected —
// one fallback pulls the same page unprojected and later calls skip the extra
// argument entirely. Keeps older SDK builds working unchanged.
let projectionSupported = true;

// Generic projected row scanner: oldest→newest so next_cursor resumes
// gap-free; dedupes by id; clamped at MAX_ROWS with `truncated` flagged so a
// partial feed is never mistaken for a complete one. Returns
// {items, truncated, maxUpdated} with items already allowlist-projected.
async function scanProjectedRows(
  entity: any,
  query: Record<string, any>,
  projection: string[] | null,
  projectRow: (row: any) => any,
  { limit = 0, maxRows = MAX_ROWS } = {},
) {
  const items: any[] = [];
  const seen = new Set<string>();
  let skip = 0;
  let rowsHit = 0;
  let truncated = false;
  let maxUpdated = '';
  while (true) {
    let page: any[] | null = null;
    if (projection && projectionSupported) {
      try {
        page = await entity.filter(query, 'updated_date', PAGE_SIZE, skip, projection);
      } catch {
        projectionSupported = false;
      }
    }
    if (page === null) page = await entity.filter(query, 'updated_date', PAGE_SIZE, skip);
    if (!Array.isArray(page)) throw new Error('Queue feed could not be verified completely.');
    rowsHit += page.length;
    for (const row of page) {
      const id = String(row?.id || '');
      if (id && seen.has(id)) continue;
      if (id) seen.add(id);
      const updated = String(row?.updated_date || '');
      if (updated && (!maxUpdated || updated > maxUpdated)) maxUpdated = updated;
      const projected = projectRow(row);
      if (projected) items.push(projected);
    }
    if (rowsHit >= maxRows) { truncated = true; break; }
    if (page.length < PAGE_SIZE) break;
    // Stop early only when the item cap is satisfied — keep scanning past it
    // otherwise (module lenses keep reading until the cap fills or the table
    // ends). A response cut by `limit` is partial even when items.length
    // lands exactly on the cap — truncated flags it either way.
    if (limit && items.length >= limit) { truncated = true; break; }
    skip += PAGE_SIZE;
  }
  return { items, truncated, maxUpdated };
}

// Bounded scoped read for the small extras tables (SavedQueueView scopes):
// paged like the gateway path but capped at `cap` rows.
async function loadScopedRows(entity: any, query: Record<string, any>, sort: string, cap = MAX_SAVED_VIEWS) {
  const rows: any[] = [];
  let skip = 0;
  const pageSize = 1000;
  while (rows.length < cap) {
    const page = await entity.filter(query, sort, pageSize, skip);
    if (!Array.isArray(page)) throw new Error('Saved view rows could not be loaded.');
    rows.push(...page);
    if (page.length < pageSize) break;
    skip += pageSize;
  }
  return rows.slice(0, cap);
}

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req), { maxRetries: 1 });
    const body = await req.json().catch(() => ({}));

    // Staff session required — every entity here is role-gated; fail closed
    // like boardFeed so a stale token gets a 401 the client can re-auth, not
    // silent service-role access. The session user also supplies the saved-
    // views owner scope — a caller can never read another user's views by
    // passing a different owner_email.
    const sessionUser = await authenticateSignShopSession(base44, body?.session_token);
    const sessionEmail = norm(sessionUser?.email);

    const feed = cleanFeed(body?.feed);
    const since = cleanSince(body?.since);
    const limit = cleanLimit(body?.limit);
    const moduleKey = cleanModuleKey(body?.module_key);
    const queueLens = cleanLens(body?.queue_lens);
    const pageKey = cleanPageKey(body?.page_key);
    cleanOwner(body?.owner_email); // validated for shape; scoping uses the session.
    const include = cleanInclude(body?.include, feed);
    // items:false — extras-only call (lens tab switch re-scopes saved views
    // without re-pulling the whole row table).
    const wantItems = body?.items !== false;

    const cacheable = !since && !limit;
    const cacheKey = queueFeedCacheKey({
      feed,
      lens: queueLens,
      pageKey,
      // my_workflow carries no owner-scoped slice — its items and extras are
      // the same rows for every session, so the key drops the owner segment
      // and one entry serves a whole-staff mount burst.
      owner: feed === 'my_workflow' ? '' : sessionEmail,
      include,
      moduleKey,
    }) + `|items:${wantItems ? 1 : 0}`;
    if (cacheable) {
      const hit = feedCacheGet(cacheKey);
      if (hit) return Response.json(hit);
    }

    const entities = base44.asServiceRole.entities;
    const payload: any = {
      feed,
      items: [],
      count: 0,
      truncated: false,
      next_cursor: since || null,
      generated_at: new Date().toISOString(),
    };
    // Per-extra failures are reported, never fatal — the client falls back to
    // its own gateway reads for exactly the missing slice (fail-open).
    const extrasErrors: Record<string, string> = {};

    // --- items: the page's row set -------------------------------------------
    if (wantItems) {
      const query: Record<string, any> = {};
      if (since) query.updated_date = { $gte: since };

      let projection: string[] | null = null;
      let projectRow: (row: any) => any = (r) => r;
      if (feed === 'product_queue') {
        projection = QUEUE_WO_FIELDS;
        projectRow = (row) => projectWorkOrder(row, moduleKey);
      } else if (feed === 'crm_events') {
        projection = CRM_ACTIVITY_FIELDS;
        // The queue only ever renders taxonomy rows — the server applies the
        // same filter so audit-trail records never cross the wire.
        query.event_type = { $in: [...CRM_EVENT_TYPES] };
        projectRow = (row) => projectCrmActivity(row);
      } else if (feed === 'estimate_queue') {
        projection = ESTIMATE_QUEUE_FIELDS;
        projectRow = (row) => projectEstimate(row);
      } else if (feed === 'my_workflow') {
        projection = GENERAL_TASK_FIELDS;
        // The gateway read the page ran was filter({completed:false},
        // 'created_date') — the server applies the same query so the open-task
        // set is identical (a since-delta can never observe a task flipping
        // completed, which is why the client asks for full pulls here).
        query.completed = false;
        projectRow = (row) => projectGeneralTask(row);
      }

      const entity =
        feed === 'crm_events' ? entities.OpportunityActivity
        : feed === 'estimate_queue' ? entities.AllInOneEstimate
        : feed === 'my_workflow' ? entities.GeneralTask
        : entities.WorkOrder;
      const scanned = await scanProjectedRows(
        entity, query, projection, projectRow, { limit },
      );

      const cappedByLimit = limit > 0 && scanned.items.length >= limit;
      const pageItems = limit > 0 ? scanned.items.slice(0, limit) : scanned.items;
      // Max updated_date *scanned* normally — resuming from it never re-reads
      // rows already returned. When the response was cut by `limit`, the
      // cursor must not advance past rows the client never received, so it
      // falls back to the max over returned items (scanned ASC, the rest
      // resume next).
      let nextCursor = scanned.maxUpdated || since || null;
      if (cappedByLimit) {
        const maxReturned = pageItems.reduce((m: string, it: any) => {
          const u = String(it?.updated_date || '');
          return u > m ? u : m;
        }, '');
        nextCursor = maxReturned || since || null;
      }
      if (feed === 'my_workflow') {
        // Row-order parity with the gateway read this replaces
        // (filter({completed:false}, 'created_date')): scan order is
        // updated_date-ascending for cursor math, so the open-task set is
        // re-sorted on the immutable created_date before it leaves.
        pageItems.sort((a: any, b: any) =>
          String(a?.created_date || '').localeCompare(String(b?.created_date || '')));
      }
      payload.items = pageItems;
      payload.count = pageItems.length;
      payload.truncated = scanned.truncated || cappedByLimit;
      payload.next_cursor = nextCursor;
    }

    // --- extras: the page's mount-time scoped reads ---------------------------
    if (include.includes('saved_views')) {
      try {
        const rows = queueLens
          ? await loadScopedRows(entities.SavedQueueView, { queue_lens: queueLens }, 'created_date')
          : await loadScopedRows(entities.SavedQueueView, {}, 'created_date');
        payload.saved_views = pageKey
          ? scopeSavedViewsForPage(rows, { pageKey, ownerEmail: sessionEmail })
          : scopeSavedViewsForLens(rows, { lens: queueLens || 'all', ownerEmail: sessionEmail });
      } catch (e: any) {
        extrasErrors.saved_views = e?.message || 'Saved views could not be loaded.';
        payload.saved_views = null;
      }
    }
    if (include.includes('settings')) {
      try {
        const rows = await entities.GlobalSettings.filter({ setting_key: SETTINGS_KEY_STAGE_MODE });
        if (!Array.isArray(rows)) throw new Error('Setting lookup did not return a record list.');
        if (rows.length > 1) throw new Error('Setting has multiple records for its key.');
        payload.settings = {
          product_stage_mode: rows[0] ? projectSettingRecord(rows[0]) : null,
        };
      } catch (e: any) {
        extrasErrors.settings = e?.message || 'Queue settings could not be loaded.';
        payload.settings = null;
      }
    }
    if (include.includes('customers')) {
      try {
        const rows = await scanProjectedRows(
          entities.Customer, {}, CRM_CUSTOMER_FIELDS, projectCrmCustomer, { maxRows: MAX_ROWS },
        );
        payload.customers = rows.items;
        if (rows.truncated) extrasErrors.customers = 'Customer list reached the row cap.';
      } catch (e: any) {
        extrasErrors.customers = e?.message || 'Customers could not be loaded.';
        payload.customers = null;
      }
    }
    if (include.includes('quote_defaults')) {
      try {
        const rows = await entities.QuoteDefaults.filter({ config_name: 'default' }, undefined, 1);
        const row = Array.isArray(rows) ? rows[0] : null;
        payload.quote_defaults = row ? projectQuoteDefaults(row) : null;
      } catch (e: any) {
        extrasErrors.quote_defaults = e?.message || 'Quote defaults could not be loaded.';
        payload.quote_defaults = null;
      }
    }
    if (include.includes('users')) {
      try {
        // The page's unfiltered AuthorizedEmail pull — the assignee pickers
        // need the whole roster, projected down to the five fields they read.
        const rows = await scanProjectedRows(
          entities.AuthorizedEmail, {}, MY_WORKFLOW_USER_FIELDS, projectWorkflowUser, { maxRows: MAX_ROWS },
        );
        payload.users = rows.items;
        if (rows.truncated) extrasErrors.users = 'User directory reached the row cap.';
      } catch (e: any) {
        extrasErrors.users = e?.message || 'The user directory could not be loaded.';
        payload.users = null;
      }
    }
    if (include.includes('dropdown_conditions')) {
      try {
        const rows = await entities.GlobalSettings.filter({ setting_key: SETTINGS_KEY_DROPDOWN_CONDITIONS });
        if (!Array.isArray(rows)) throw new Error('Setting lookup did not return a record list.');
        if (rows.length > 1) throw new Error('Setting has multiple records for its key.');
        payload.dropdown_conditions = rows[0] ? projectSettingRecord(rows[0]) : null;
      } catch (e: any) {
        extrasErrors.dropdown_conditions = e?.message || 'Dropdown conditions could not be loaded.';
        payload.dropdown_conditions = null;
      }
    }
    if (include.includes('task_descriptions')) {
      try {
        const rows = await entities.GlobalSettings.filter({ setting_key: SETTINGS_KEY_TASK_DESCRIPTIONS });
        if (!Array.isArray(rows)) throw new Error('Setting lookup did not return a record list.');
        if (rows.length > 1) throw new Error('Setting has multiple records for its key.');
        payload.task_descriptions = rows[0] ? projectSettingRecord(rows[0]) : null;
      } catch (e: any) {
        extrasErrors.task_descriptions = e?.message || 'Task descriptions could not be loaded.';
        payload.task_descriptions = null;
      }
    }

    payload.projected_fields = {
      items:
        feed === 'crm_events' ? CRM_ACTIVITY_FIELDS
        : feed === 'estimate_queue' ? ESTIMATE_QUEUE_FIELDS
        : feed === 'my_workflow' ? GENERAL_TASK_FIELDS
        : QUEUE_WO_FIELDS,
      product: feed === 'product_queue' ? QUEUE_PRODUCT_FIELDS : undefined,
      saved_view: include.includes('saved_views') ? SAVED_VIEW_FIELDS : undefined,
      customer: include.includes('customers') ? CRM_CUSTOMER_FIELDS : undefined,
      quote_defaults: include.includes('quote_defaults') ? QUOTE_DEFAULTS_FIELDS : undefined,
      user: include.includes('users') ? MY_WORKFLOW_USER_FIELDS : undefined,
    };
    if (Object.keys(extrasErrors).length) payload.extras_errors = extrasErrors;
    if (cacheable) feedCacheSet(cacheKey, payload);
    return Response.json(payload);
  } catch (error: any) {
    const status = Number(error?.status || error?.response?.status || 500);
    if ([400, 401, 403, 429].includes(status)) {
      return Response.json({ error: error?.message || 'Queue feed failed.' }, { status });
    }
    console.error('queueFeed error:', error);
    return Response.json({ error: 'Data could not be loaded. Try again.' }, { status: 500 });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.25';
import { authenticateSignShopSession } from '../../shared/signShopSession.ts';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { FEED_FIELDS } from '../../shared/boardFeedFields.ts';

// Board/list feed for the app's largest tables. Workflow boards used to page
// the full WorkOrder table (~3.1k rows, ~15 MB) through entity reads on every
// mount and again on every poll, which saturated the shared entity_list rate
// budget and produced user-facing 500s. This endpoint exists to make those
// reads survivable:
//   - HEAVY_FIELDS are stripped per entity (~70% of WorkOrder bytes are the
//     smartsheet_sync_snapshot + work_notes blobs, which list views never
//     read; detail dialogs fetch single rows when they need them).
//   - `since` applies an updated_date delta cursor server-side, so a steady
//     board refresh transfers only changed rows in one read instead of
//     re-paging the whole table.
// Read scope matches these entities' open read RLS — a valid staff session is
// accepted when presented but is not required to read.

const FEEDABLE: Record<string, { heavy: string[] }> = {
  WorkOrder: { heavy: ['smartsheet_sync_snapshot', 'work_notes', 'sales_import_snapshot', 'smartsheet_create_attempt'] },
  Order: { heavy: ['smartsheet_sync_snapshot', 'work_notes', 'smartsheet_create_attempt'] },
  JurisdictionProfile: { heavy: [] },
};

const ALLOWED_OPERATORS = new Set(['$ne', '$gt', '$gte', '$lt', '$lte', '$in', '$nin']);
const MAX_QUERY_BYTES = 4000;
// One 5k page pulls the whole active table in a single entity_list call
// (~2-5s) instead of ~7 sequential 500-row pages — both faster for the
// caller and ~7x cheaper against the shared entity_list rate budget.
const PAGE_SIZE = 5000;
const MAX_ROWS = 20000;
const MAX_FIELD_LIST = 200;
const SORT_PATTERN = /^(-?[A-Za-z_][\w.]*)(\s*,\s*-?[A-Za-z_][\w.]*){0,3}$/;

function bad(message: string) {
  return Object.assign(new Error(message), { status: 400 });
}

function cleanQuery(value: unknown) {
  if (value == null) return null;
  if (typeof value !== 'object' || Array.isArray(value)) {
    throw bad('Feed filter must be an object.');
  }
  const stack: any[] = [value];
  while (stack.length) {
    const node = stack.pop();
    if (!node || typeof node !== 'object') continue;
    for (const [key, val] of Object.entries(node)) {
      if (key.startsWith('$') && !ALLOWED_OPERATORS.has(key)) {
        throw bad(`Feed filter operator is not permitted: ${key}`);
      }
      if (val && typeof val === 'object') stack.push(val);
    }
  }
  let serialized;
  try {
    serialized = JSON.stringify(value);
  } catch {
    throw bad('Feed filter must be JSON-serializable.');
  }
  if (serialized.length > MAX_QUERY_BYTES) throw bad('Feed filter is too large.');
  return value;
}

function cleanSort(value: unknown) {
  const sort = String(value || '').trim();
  if (!sort) return null;
  if (sort.length > 200 || !SORT_PATTERN.test(sort)) throw bad('Feed sort is invalid.');
  return sort;
}

function cleanFields(value: unknown) {
  if (value == null) return null;
  if (!Array.isArray(value) || value.length > MAX_FIELD_LIST) throw bad('Feed fields list is invalid.');
  const out = [...new Set(value.map((f) => String(f || '').trim()).filter((f) => /^[A-Za-z_][\w.]*$/.test(f)))];
  return out.length ? out : null;
}

function cleanSince(value: unknown) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const ms = Date.parse(raw);
  if (!Number.isFinite(ms)) throw bad('Feed cursor is invalid.');
  return new Date(ms).toISOString();
}

function projectRow(row: any, fields: string[] | null, heavy: string[]) {
  if (!row || typeof row !== 'object') return row;
  if (fields) {
    const out: any = { id: row.id, created_date: row.created_date, updated_date: row.updated_date };
    for (const field of fields) out[field] = row[field];
    return out;
  }
  const clean = { ...row };
  for (const field of heavy) delete clean[field];
  return clean;
}

// Module-scope result cache — Deno isolates are reused across invocations,
// so a burst of identical full pulls (post-publish reloads, many staff tabs
// opening at once) collapses to one upstream read set instead of ~7 paged
// entity reads per tab. Delta pulls and custom projections are never
// cached; the cached payload keeps its own server_time so the caller
// delta cursor still covers the gap. Keyed per (entity|query|sort) — the
// board polls WorkOrder AND Order, and a single-slot cache thrashed on
// every alternating pull, collapsing each hit into a cold full-table scan.
const feedCache = new Map<string, { payload: any; expires: number; at: number }>();
const FEED_CACHE_TTL_MS = 30_000;
const FEED_CACHE_MAX_KEYS = 16;
function feedCacheGet(key: string) {
  const hit = feedCache.get(key);
  if (!hit) return null;
  if (hit.expires <= Date.now()) {
    feedCache.delete(key);
    return null;
  }
  return hit.payload;
}
function feedCacheSet(key: string, payload: any) {
  if (feedCache.size >= FEED_CACHE_MAX_KEYS) {
    // Evict expired entries first, then the oldest — a full cache must never
    // grow unbounded.
    const now = Date.now();
    for (const [k, v] of feedCache) {
      if (v.expires <= now) feedCache.delete(k);
    }
  }
  if (feedCache.size >= FEED_CACHE_MAX_KEYS) {
    let oldestKey: string | null = null;
    let oldestAt = Infinity;
    for (const [k, v] of feedCache) {
      if (v.at < oldestAt) { oldestAt = v.at; oldestKey = k; }
    }
    if (oldestKey !== null) feedCache.delete(oldestKey);
  }
  feedCache.set(key, { payload, expires: Date.now() + FEED_CACHE_TTL_MS, at: Date.now() });
}
// Set false permanently for the isolate if a projected filter is rejected —
// one fallback pulls the same page unprojected, and later calls skip the
// extra argument entirely. Keeps older SDK builds working unchanged.
let projectionSupported = true;

Deno.serve(async (req) => {
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req), { maxRetries: 1 });
    const body = await req.json().catch(() => ({}));

    // Staff session required — WorkOrder/Order read RLS is role-gated, so an
    // anonymous service-role feed would reopen the access that lockdown closed.
    // The earlier .catch(() => null) let anonymous callers pull the whole feed;
    // fail closed instead — a stale token gets a 401 the client can re-auth,
    // not silent access to every work order on file.
    await authenticateSignShopSession(base44, body.session_token);

    const entityName = String(body?.entity || '').trim();
    const spec = FEEDABLE[entityName];
    if (!spec) return Response.json({ error: 'This record type cannot be read here.' }, { status: 403 });

    const query = cleanQuery(body?.query) || {};
    const since = cleanSince(body?.since);
    if (since) {
      query.updated_date = { ...(query.updated_date && typeof query.updated_date === 'object' ? query.updated_date : {}), $gt: since };
    }
    const sort = cleanSort(body?.sort) || '-updated_date';
    const fields = cleanFields(body?.fields);
    const includeHeavy = body?.include_heavy === true;
    const heavy = includeHeavy ? [] : spec.heavy;
    // Server-side projection — the SDK's 5th filter arg keeps the heavy sync
    // blobs out of the entity read itself (~85% of WorkOrder row bytes),
    // instead of transferring them and stripping them in projectRow. Caller
    // field lists are pushed down too; the system fields dedupe and the
    // delta cursor need ride along either way.
    const projection = includeHeavy
      ? null
      : fields
        ? [...new Set([...fields, 'id', 'created_date', 'updated_date'])]
        : FEED_FIELDS[entityName] || null;
    const cacheable = !since && !fields && !includeHeavy;
    const cacheKey = entityName + "|" + JSON.stringify(query) + "|" + sort;
    if (cacheable) {
      const hit = feedCacheGet(cacheKey);
      if (hit) return Response.json(hit);
    }

    const entity = base44.asServiceRole.entities[entityName];
    const rows: any[] = [];
    const seen = new Set<string>();
    let skip = 0;
    let rowsHit = 0;
    let truncated = false;
    while (true) {
      let page: any[] | null = null;
      if (projection && projectionSupported) {
        try {
          page = await entity.filter(query, sort, PAGE_SIZE, skip, projection);
        } catch {
          projectionSupported = false;
        }
      }
      if (page === null) page = await entity.filter(query, sort, PAGE_SIZE, skip);
      if (!Array.isArray(page)) throw new Error(`${entityName} feed could not be verified completely.`);
      rowsHit += page.length;
      for (const row of page) {
        const id = String(row?.id || '');
        if (id && seen.has(id)) continue;
        if (id) seen.add(id);
        rows.push(projectRow(row, fields, heavy));
      }
      // A pull that scans MAX_ROWS rows is clamped — flag it on every pull
      // type (full and delta alike) so callers never mistake a partial feed
      // for a complete one.
      if (rowsHit >= MAX_ROWS) { truncated = true; break; }
      if (page.length < PAGE_SIZE) break;
      skip += PAGE_SIZE;
    }

    const payload = {
      rows,
      count: rows.length,
      truncated,
      server_time: new Date().toISOString(),
    };
    if (cacheable) feedCacheSet(cacheKey, payload);
    return Response.json(payload);
  } catch (error: any) {
    const status = Number(error?.status || error?.response?.status || 500);
    if ([400, 401, 403, 429].includes(status)) {
      return Response.json({ error: error?.message || 'Board feed failed.' }, { status });
    }
    console.error('boardFeed error:', error);
    return Response.json({ error: 'Data could not be loaded. Try again.' }, { status: 500 });
  }
});

